    :mode="popupMode"
    :row-data="selectedRow"
    @close="isPopupVisible = false"
    @save="handleSave"
  />
</template>

<script>
// @ is an alias to /src
import boxDetails from "@/components/dashboard/boxDetails.vue";
import productPopup from "@/components/dashboard/popus/productPopup.vue";
import axios from "axios";
import SvgIcon from "@/components/SvgIcon.vue";
import LoadingHere from "@/components/LoadingHere.vue"; // Import LoadingHere component
import { useToast } from "vue-toastification";

export default {
  name: "ProductManagement",
  setup() {
    const toast = useToast();
    return { toast };
  },
  components: {
    boxDetails,
    productPopup,
    SvgIcon,
    LoadingHere,
  },
  data() {
    return {
      filter: "",

      rows: [
        // More products here
      ],
      isPopupVisible: false,
      popupMode: "",
      selectedRow: null,
      isLoading: false, // Add loading state
    };
  },
  computed: {
    filteredRows() {
      return this.rows.filter((row) => {
        const searchTerm = this.filter.toLowerCase();
        return (
          (row.name && row.name.toLowerCase().includes(searchTerm)) || // Filter by name
          (row.productCategory &&
            row.productCategory.toLowerCase().includes(searchTerm)) || // Filter by category
          (row.description && row.description.toLowerCase().includes(searchTerm)) || // Filter by description
          (row.price && row.price.toString().includes(searchTerm)) // Filter by price
        );
      });
    },
  },
  mounted() {
    this.isLoading = true; // Set loading state to true
    this.FetchRows(); // Fetch rows dynamically
    this.fetchUserData(); // Fetch user data dynamically
  },
  methods: {
    fetchUserData() {
      // Simulate fetching user data from an API or store
    },
    FetchRows() {
      const token = localStorage.getItem("authToken");
      axios
        .get(
          "https://backend.alaqdk.com/api/v1/admin/dashboard/get-all-products",
          {
            headers: {
              "Accept-Language": this.$i18n.locale || "ar",
              Authorization: `Bearer ${token}`,
            },
          }
        )
        .then((response) => {
          this.isLoading = false;

          console.log("product Response Data:", response.data);
          const data = response.data;
          if (data.status || data.success) {
            this.rows = data.data.map((product) => ({
              id: product.id,
              cover_image: product.cover_image || product.image || "N/A",
              name: product.name || "N/A",
              nameAr: product.name_ar || product.name || "N/A",
              nameEn: product.name_en || product.name || "N/A",
              productCategory: product.productCategory?.name || product.category?.name || product.category || "N/A",
              product_category_id: product.product_category_id || product.category_id || "",
              description: product.description || "N/A",
              price: product.price || "N/A",
              calories: product.calories || "",
              restaurantId: product.restaurant_id || product.restaurant?.id || "",
              restaurant_id: product.restaurant_id || product.restaurant?.id || "",
              currentlyAvailable: product.currently_available || product.is_available || "N/A",
              currently_available: product.currently_available || product.is_available || "N/A",
            }));
            console.log("Processed Rows:", this.rows);
          } else {
            console.error("Failed to fetch rows data:", data.message);
            this.toast.error(data.message || "Failed to fetch products");
          }
        })
        .catch((error) => {
          this.isLoading = false;
          console.error("Error fetching rows data:", error);
          
          if (error.response?.status === 401) {
            this.toast.error("Authentication failed. Please login again.");
          } else if (error.response?.status === 403) {
            this.toast.error("You don't have permission to access this resource.");
          } else {
            this.toast.error("Failed to fetch products. Please try again.");
          }
        });
    },
    openPopup(mode, row = null) {
      this.popupMode = mode;
      this.selectedRow = row || {
        id: null,
        cover_image: "",
        name: "",
        productCategory: "",
        description: "",
        price: "",
        currentlyAvailable: "",
      };
      this.isPopupVisible = true;
    },
    async handleSave(updatedRow) {
      if (this.popupMode === "add") {
        try {
          this.isLoading = true;
          const token = localStorage.getItem("authToken");
          
          if (!token) {
            this.toast.error("Authentication token not found. Please login again.");
            return;
          }
          
          // Prepare the data for the API using FormData
          const formData = new FormData();
          
          // Add all the required fields
          formData.append('name[ar]', updatedRow['name[ar]']);
          formData.append('name[en]', updatedRow['name[en]']);
          formData.append('description', updatedRow.description);
          formData.append('price', updatedRow.price);
          formData.append('restaurant_id', updatedRow.restaurant_id);
          formData.append('product_category_id', updatedRow.product_category_id);
          formData.append('calories', updatedRow.calories);
          formData.append('currently_available', updatedRow.currently_available);
          
          // Handle image upload
          if (updatedRow['images[0][image]']) {
            formData.append('images[0][image]', updatedRow['images[0][image]']);
          }

          const response = await axios.post(
            "https://backend.alaqdk.com/api/v1/admin/products/store-product",
            formData,
            {
              headers: {
                "Accept-Language": this.$i18n.locale || "ar",
                Authorization: `Bearer ${token}`,
                "Content-Type": "multipart/form-data",
              },
            }
          );

          console.log("API Response:", response.data);

          if (response.data.status || response.data.success) {
            // Add the new product to the table
            const newProduct = {
              id: response.data.data?.id || Math.floor(Math.random() * 10000) + 1000,
              cover_image: response.data.data?.images?.[0]?.image || updatedRow.cover_image,
              name: updatedRow['name[ar]'] || updatedRow['name[en]'], // Use Arabic name as primary display
              productCategory: updatedRow.product_category_id,
              description: updatedRow.description,
              price: updatedRow.price,
              calories: updatedRow.calories,
              restaurantId: updatedRow.restaurant_id,
              currentlyAvailable: updatedRow.currently_available,
            };
            this.rows.push(newProduct);
            
            this.toast.success("Product added successfully!");
            this.isPopupVisible = false;
            
            // Refresh the product list to get the latest data from server
            this.FetchRows();
          } else {
            this.toast.error(response.data.message || "Failed to add product");
          }
        } catch (error) {
          console.error("Error adding product:", error);
          this.handleApiError(error, "adding product");
        } finally {
          this.isLoading = false;
        }
      } else if (this.popupMode === "edit") {
        try {
          this.isLoading = true;
          const token = localStorage.getItem("authToken");
          
          if (!token) {
            this.toast.error("Authentication token not found. Please login again.");
            return;
          }
          
          // Prepare the data for the API using FormData - same format as add product
          const formData = new FormData();
          
          // Add all the required fields - same format as add product
          formData.append('name[ar]', updatedRow['name[ar]']);
          formData.append('name[en]', updatedRow['name[en]']);
          formData.append('description', updatedRow.description);
          formData.append('price', updatedRow.price);
          formData.append('restaurant_id', updatedRow.restaurant_id);
          formData.append('product_category_id', updatedRow.product_category_id);
          formData.append('calories', updatedRow.calories);
          formData.append('currently_available', updatedRow.currently_available);
          formData.append('_method', 'PUT');
          
          // Handle image upload - same format as add product
          if (updatedRow['images[0][image]']) {
            formData.append('images[0][image]', updatedRow['images[0][image]']);
          }

          const response = await axios.post(
            `https://backend.alaqdk.com/api/v1/admin/products/${updatedRow.id}`,
            formData,
            {
              headers: {
                "Accept-Language": this.$i18n.locale || "ar",
                Authorization: `Bearer ${token}`,
                "Content-Type": "multipart/form-data",
              },
            }
          );

          console.log("Edit API Response:", response.data);

          if (response.data.status || response.data.success) {
            // Update the product in the table
            const index = this.rows.findIndex((r) => r.id === updatedRow.id);
            if (index !== -1) {
              this.rows.splice(index, 1, updatedRow);
            }
            
            this.toast.success("Product updated successfully!");
            this.isPopupVisible = false;
            
            // Refresh the product list
            this.FetchRows();
          } else {
            this.toast.error(response.data.message || "Failed to update product");
          }
        } catch (error) {
          console.error("Error updating product:", error);
          this.handleApiError(error, "updating product");
        } finally {
          this.isLoading = false;
        }
      } else if (this.popupMode === "delete") {
        try {
          this.isLoading = true;
          const token = localStorage.getItem("authToken");
          
          if (!token) {
            this.toast.error("Authentication token not found. Please login again.");
            return;
          }

          const response = await axios.delete(
            `https://backend.alaqdk.com/api/v1/admin/products/${updatedRow.id}`,
            {
              headers: {
                "Accept-Language": this.$i18n.locale || "ar",
                Authorization: `Bearer ${token}`,
              },
            }
          );

          console.log("Delete API Response:", response.data);

          if (response.data.status || response.data.success) {
            // Remove the product from the table
            this.rows = this.rows.filter((r) => r.id !== updatedRow.id);
            
            this.toast.success("Product deleted successfully!");
            this.isPopupVisible = false;
          } else {
            this.toast.error(response.data.message || "Failed to delete product");
          }
        } catch (error) {
          console.error("Error deleting product:", error);
          this.handleApiError(error, "deleting product");
        } finally {
          this.isLoading = false;
        }
      }
    },
    handleApiError(error, operation) {
      if (error.response) {
        console.error("Error response data:", error.response.data);
        const errorMessage = error.response.data.message || 
                           error.response.data.error || 
                           `Server error occurred while ${operation}`;
        this.toast.error(errorMessage);
      } else if (error.request) {
        this.toast.error("Network error. Please check your connection.");
      } else {
        this.toast.error(`Error ${operation}. Please try again.`);
      }
    },
    handleImageError(event) {
      event.target.src = "https://via.placeholder.com/50x50?text=No+Image";
    },

    formatDate(dateString) {
      if (!dateString || dateString === "N/A") {
        return "N/A";
      }
      
      try {
        const date = new Date(dateString);
        
        // Check if date is valid
        if (isNaN(date.getTime())) {
          return "Invalid Date";
        }
        
        // Compact date format - always use Gregorian calendar
        const options = {
          year: '2-digit',
          month: '2-digit',
          day: '2-digit',
          hour: '2-digit',
          minute: '2-digit',
          calendar: 'gregory' // Force Gregorian calendar
        };
        
        return date.toLocaleDateString(this.$i18n.locale === 'ar' ? 'ar-SA-u-ca-gregory' : 'en-US', options);
      } catch (error) {
        console.error('Error formatting date:', error);
        return dateString;
      }
    },
  },
};
