<script>
import { useToast } from "vue-toastification";
import axiosInstance from "../../../axios.js";
import { getLocalizedNameWithI18n } from "@/utils/localization.js";

export default {
  setup() {
    const toast = useToast();
    return { toast };
  },
  props: {
    mode: { type: String, required: true },
    rowData: { type: Object, default: () => ({}) },
  },
  data() {
    return {
      formData: {
        id: null,
        cover_image: "",
        nameAr: "",
        nameEn: "",
        productCategory: "",
        description: "",
        price: "",
        calories: "",
        restaurantId: "",
        currentlyAvailable: "",
      },
      errors: {
        nameAr: "",
        nameEn: "",
        productCategory: "",
        description: "",
        price: "",
        calories: "",
        restaurantId: "",
      },
      categories: [],
      restaurants: [],
      loading: false,
      loadingRestaurants: false,
    };
  },
  computed: {
    selectedCategoryName() {
      if (!this.formData.productCategory) return "";
      
      // First try to find in the categories list
      const category = this.categories.find(cat => cat.id == this.formData.productCategory);
      if (category) return category.name;
      
      // If not found in list, try to get from the original rowData (for view mode)
      if (this.rowData && this.rowData.productCategory) {
        if (typeof this.rowData.productCategory === 'string') {
          return this.rowData.productCategory;
        } else if (this.rowData.productCategory.name) {
          return this.rowData.productCategory.name;
        }
      }
      
      return "";
    },
    selectedRestaurantName() {
      if (!this.formData.restaurantId) return "";
      
      // First try to find in the restaurants list
      const restaurant = this.restaurants.find(rest => rest.id == this.formData.restaurantId);
      if (restaurant) return restaurant.name;
      
      // If not found in list, try to get from the original rowData (for view mode)
      if (this.rowData && this.rowData.restaurant) {
        if (typeof this.rowData.restaurant === 'string') {
          return this.rowData.restaurant;
        } else if (this.rowData.restaurant.name) {
          return this.rowData.restaurant.name;
        }
      }
      
      return "";
    }
  },
  watch: {
    rowData: {
      immediate: true,
      handler(newVal) {
        if (newVal && Object.keys(newVal).length > 0) {
          // For edit mode, fetch complete product details by ID
          if (this.mode === 'edit' && newVal.id) {
            this.fetchProductById(newVal.id);
          } else {
            // Map the incoming data to form fields for view mode
            this.mapProductData(newVal);
          }
        } else {
          // Reset form data for add mode
          this.resetFormData();
        }
      },
    },
  },
  async mounted() {
    await Promise.all([
      this.fetchCategories(),
      this.fetchRestaurants()
    ]);
  },
  methods: {
    async fetchProductById(productId) {
      try {
        // First ensure categories and restaurants are loaded
        await Promise.all([
          this.fetchCategories(),
          this.fetchRestaurants()
        ]);
        
        const response = await axiosInstance.get(`v1/admin/products/${productId}`);
        if (response.data.status) {
          const productData = response.data.data;
          console.log('Product data from API:', productData);
          this.mapProductData(productData);
        } else {
          this.toast.error(this.$t("ErrorLoadingProduct") || "Error loading product details");
        }
      } catch (error) {
        console.error('Error fetching product by ID:', error);
        this.toast.error(this.$t("ErrorLoadingProduct") || "Error loading product details");
      }
    },
    mapProductData(productData) {
      console.log('Mapping product data:', productData);
      console.log('Available categories:', this.categories);
      console.log('Available restaurants:', this.restaurants);
      
      // Map the complete product data to form fields
      this.formData = {
        id: productData.id || null,
        cover_image: productData.cover_image || (productData.image && productData.image[0] ? productData.image[0].image : "") || "",
        nameAr: productData.name_ar || productData.name || "",
        nameEn: productData.name_en || productData.name || "",
        productCategory: String(productData.productCategory?.id || productData.product_category_id || ""),
        description: productData.description || "",
        price: productData.price || "",
        calories: productData.calories || "",
        restaurantId: String(productData.productCategory?.restaurant_id || productData.restaurant_id || ""),
        currentlyAvailable: String(productData.currently_available || productData.is_available || ""),
      };
      
      console.log('Mapped form data:', this.formData);
      console.log('Product category ID:', this.formData.productCategory);
      console.log('Restaurant ID:', this.formData.restaurantId);
      
      // Use $nextTick to ensure DOM is updated
      this.$nextTick(() => {
        console.log('After nextTick - Product category ID:', this.formData.productCategory);
        console.log('After nextTick - Restaurant ID:', this.formData.restaurantId);
      });
    },
    resetFormData() {
      // Reset form data for add mode
      this.formData = {
        id: null,
        cover_image: "",
        nameAr: "",
        nameEn: "",
        productCategory: "",
        description: "",
        price: "",
        calories: "",
        restaurantId: "",
        currentlyAvailable: "",
      };
    },
    async fetchCategories() {
      this.loading = true;
      try {
        const response = await axiosInstance.get('v1/admin/product-categories');
        if (response.data.status) {
          this.categories = response.data.data;
        } else {
          this.toast.error(this.$t("ErrorLoadingCategories") || "Error loading categories");
        }
      } catch (error) {
        console.error('Error fetching categories:', error);
        this.toast.error(this.$t("ErrorLoadingCategories") || "Error loading categories");
      } finally {
        this.loading = false;
      }
    },
    async fetchRestaurants() {
      this.loadingRestaurants = true;
      try {
        const response = await axiosInstance.get('v1/admin/restaurants');
        if (response.data.status) {
          this.restaurants = response.data.data.map((item) => ({
            id: item.id,
            name: getLocalizedNameWithI18n(item.name, this.$i18n) || "N/A",
          }));
        } else {
          this.toast.error(this.$t("ErrorLoadingRestaurants") || "Error loading restaurants");
        }
      } catch (error) {
        console.error('Error fetching restaurants:', error);
        this.toast.error(this.$t("ErrorLoadingRestaurants") || "Error loading restaurants");
      } finally {
        this.loadingRestaurants = false;
      }
    },
    save() {
      // Reset errors
      this.errors = {
        nameAr: "",
        nameEn: "",
        productCategory: "",
        description: "",
        price: "",
        calories: "",
        restaurantId: "",
        cover_image: "",
      };

      // Validate inputs
      let isValid = true;

      if (!this.formData.nameAr || this.formData.nameAr.trim() === '') {
        this.errors.nameAr = this.$t("ArabicNameRequired");
        isValid = false;
      }

      if (!this.formData.nameEn || this.formData.nameEn.trim() === '') {
        this.errors.nameEn = this.$t("EnglishNameRequired");
        isValid = false;
      }

      if (!this.formData.productCategory || this.formData.productCategory.toString().trim() === '') {
        this.errors.productCategory = this.$t("CategoryRequired");
        isValid = false;
      }

      if (!this.formData.description || this.formData.description.trim() === '') {
        this.errors.description = this.$t("DescriptionRequired");
        isValid = false;
      }

      if (!this.formData.price || parseFloat(this.formData.price) <= 0) {
        this.errors.price = this.$t("PriceRequired");
        isValid = false;
      }

      if (!this.formData.calories || parseInt(this.formData.calories) < 0) {
        this.errors.calories = this.$t("CaloriesRequired");
        isValid = false;
      }

      if (!this.formData.restaurantId || this.formData.restaurantId.toString().trim() === '') {
        this.errors.restaurantId = this.$t("RestaurantRequired");
        isValid = false;
      }

      if (this.formData.currentlyAvailable === '') {
        this.errors.currentlyAvailable = this.$t("StatusRequired");
        isValid = false;
      }

      // Validate image presence for add mode only
      if (this.mode === "add" && !this.formData.cover_image) {
        this.errors.cover_image = this.$t("ImageRequired");
        isValid = false;
      }

      if (!isValid) {
        this.toast.error(this.$t("FormErrors"));
        return;
      }

      // Prepare data for API
      const apiData = {
        'id': this.formData.id, // Add the ID for edit operations
        'name[ar]': this.formData.nameAr,
        'name[en]': this.formData.nameEn,
        'description': this.formData.description,
        'price': this.formData.price,
        'restaurant_id': this.formData.restaurantId,
        'product_category_id': this.formData.productCategory,
        'calories': this.formData.calories,
        'currently_available': this.formData.currentlyAvailable
      };

      // Add image if exists
      if (this.formData.cover_image && this.formData.cover_image.startsWith('data:')) {
        // Convert base64 to blob
        this.processImageForAPI(apiData);
      } else if (this.formData.imageFile && this.formData.imageFile instanceof File) {
        apiData['images[0][image]'] = this.formData.imageFile;
        this.$emit("save", apiData);
      } else {
        this.$emit("save", apiData);
      }
    },
    async processImageForAPI(apiData) {
      try {
        const response = await fetch(this.formData.cover_image);
        const blob = await response.blob();
        apiData['images[0][image]'] = blob;
        this.$emit("save", apiData);
      } catch (error) {
        console.error('Error processing image:', error);
        this.toast.error(this.$t("ErrorProcessingImage") || "Error processing image");
      }
    },
    deleteRow() {
      this.$emit("save", this.rowData);
    },
    handleImageUpload(event) {
      const file = event.target.files[0];
      this.processFile(file);
    },
    handleDrop(event) {
      event.preventDefault();
      const file = event.dataTransfer.files[0];
      this.processFile(file);
    },
    processFile(file) {
      if (!file) {
        this.toast.error(this.$t("NoFileSelected"));
        return;
      }

      // Validate file type
      const validTypes = ['image/jpeg', 'image/jpg', 'image/png', 'image/gif', 'image/webp'];
      if (!validTypes.includes(file.type)) {
        this.toast.error(this.$t("InvalidImageType") || "Please select a valid image file (JPEG, PNG, GIF, WebP)");
        return;
      }

      // Validate file size (max 5MB)
      const maxSize = 5 * 1024 * 1024; // 5MB
      if (file.size > maxSize) {
        this.toast.error(this.$t("ImageTooLarge") || "Image size should be less than 5MB");
        return;
      }

      const reader = new FileReader();
      reader.onload = (e) => {
        const img = new Image();
        img.onload = () => {
          // Validate image dimensions (max width: 3000px, max height: 3000px)
          const maxWidth = 3000;
          const maxHeight = 3000;
          if (img.width > maxWidth || img.height > maxHeight) {
            this.toast.error(this.$t("ImageDimensionsTooLarge") || "Image dimensions should be less than 3000x3000 pixels");
            return;
          }
          
          // Store both the base64 data and the file object
          this.formData.cover_image = e.target.result;
          this.formData.imageFile = file; // Store the file object for upload
        };
        img.onerror = () => {
          this.toast.error(this.$t("InvalidImageFile") || "Invalid image file");
        };
        img.src = e.target.result;
      };
      reader.onerror = () => {
        this.toast.error(this.$t("ErrorReadingFile") || "Error reading file");
      };
      reader.readAsDataURL(file);
    },
    triggerFileInput() {
      this.$refs.fileInput.click();
    },
  },
};
</script>

