/**
 * Utility functions for handling localized content
 */

/**
 * Get localized name from an object or string
 * @param {Object|string} name - The name object with ar/en properties or a string
 * @param {string} locale - The current locale (ar/en)
 * @returns {string} - The localized name
 */
export function getLocalizedName(name, locale = 'en') {
  // Handle different name formats
  if (!name) return "";
  
  // If name is already a string, return it
  if (typeof name === 'string') {
    return name;
  }
  
  // If name is an object with ar/en properties
  if (typeof name === 'object' && name !== null) {
    // Return the localized name based on current locale
    if (locale === 'ar' && name.ar) {
      return name.ar;
    } else if (locale === 'en' && name.en) {
      return name.en;
    }
    
    // Fallback: return the first available name
    if (name.ar) return name.ar;
    if (name.en) return name.en;
    
    // If no localized name is available, return a default
    return "Restaurant";
  }
  
  return "";
}

/**
 * Get localized name using Vue i18n instance
 * @param {Object|string} name - The name object with ar/en properties or a string
 * @param {Object} i18n - Vue i18n instance
 * @returns {string} - The localized name
 */
export function getLocalizedNameWithI18n(name, i18n) {
  return getLocalizedName(name, i18n.locale);
} 