<script>
import { useToast } from "vue-toastification";
import axios from "axios";

export default {
  props: {
    type: { type: String, required: true },
    row: { type: Object, required: true },
  },
  setup() {
    const toast = useToast();
    return { toast };
  },
  data() {
    return {
      formData: {
        nameEn: '',
        nameAr: '',
        email: '',
        phone: '', // full international phone
      },
      errors: {},
      isSubmitting: false,
      isDeleting: false,
      isApproving: false,
      isPhoneValid: true, // Track phone validation state
    };
  },

  computed: {
    filteredFormData() {
      // Only show nameEn, nameAr, email, phone in edit/add
      if (this.type === 'edit' || this.type === 'add') {
        return {
          nameEn: this.formData.nameEn,
          nameAr: this.formData.nameAr,
          email: this.formData.email,
          phone: this.formData.phone,
        };
      }
      // For view, keep previous logic (excluding approved, etc.)
      const formDataWithoutId = { ...this.formData };
      delete formDataWithoutId.id;
      delete formDataWithoutId.lastPurchase;
      delete formDataWithoutId.productCount;
      delete formDataWithoutId.orderCount;
      delete formDataWithoutId.approved;
      return formDataWithoutId;
    }
  },

  watch: {
    row: {
      immediate: true,
      async handler(newRow) {
        if (this.type === "add") {
          this.formData = {
            nameEn: "",
            nameAr: "",
            email: "",
            phone: "",
          };
        } else if (this.type === "view" && newRow.id) {
          try {
            const token = localStorage.getItem("authToken");
            const headers = {
              "Accept-Language": this.$i18n.locale === 'ar' ? 'ar' : 'en',
              Authorization: `Bearer ${token}`,
            };
            const response = await axios.get(
              `https://backend.alaqdk.com/api/v1/admin/restaurants/${newRow.id}`,
              { headers }
            );
            const data = response.data.data;
            console.log('View restaurant data:', data); // Debug log
            
            // Ensure phone number has proper format
            let phoneNumber = data.phone || "";
            if (phoneNumber && !phoneNumber.startsWith('+')) {
              phoneNumber = '+' + phoneNumber;
            }
            
            this.formData = {
              nameEn: data.name || "",
              nameAr: data.name || "",
              email: data.email || "",
              phone: phoneNumber,
            };
            console.log('Form data set for view:', this.formData); // Debug log
            console.log('Phone number formatted:', phoneNumber); // Debug log
            
            // Ensure the component updates after data is set
            this.$nextTick(() => {
              console.log('After nextTick - phone value:', this.formData.phone);
            });
          } catch (error) {
            console.error('Error fetching restaurant data:', error);
            // Fallback to parent component data
            this.formData = {
              nameEn: newRow.restName || "",
              nameAr: newRow.restName || "",
              email: newRow.email || "",
              phone: newRow.phone || "",
            };
          }
        } else {
          this.formData = {
            id: newRow.id,
            nameEn: newRow.restName || "",
            nameAr: newRow.restName || "",
            email: newRow.email || "",
            phone: newRow.phone || "",
          };
        }
      },
    },
  },
  methods: {
    onPhoneInput(phoneObj) {
      console.log('Phone input:', phoneObj); // Debug log
      
      // Handle different event types from vue-tel-input
      if (phoneObj && typeof phoneObj === 'object' && phoneObj.number !== undefined) {
        // This is a proper phone object
        this.formData.phone = phoneObj.number;
        this.isPhoneValid = phoneObj.valid;
      } else if (phoneObj && typeof phoneObj === 'object' && phoneObj.target) {
        // This is a DOM event, get the value from the target
        const inputValue = phoneObj.target.value;
        if (inputValue) {
          this.formData.phone = inputValue;
          // For DOM events, we'll assume it's valid if it has content
          this.isPhoneValid = inputValue.length >= 7;
        }
      }
      
      // Clean the phone number for storage (remove spaces, dashes, etc.)
      if (this.formData.phone) {
        this.formData.phone = this.formData.phone.replace(/[\s\-()]/g, '');
      }
      
      // Clear phone error when user starts typing
      if (this.errors.phone) {
        delete this.errors.phone;
      }
    },
    onPhoneBlur(phoneObj) {
      console.log('Phone blur:', phoneObj); // Debug log
      
      // Handle blur event - try to get the current value
      if (phoneObj && typeof phoneObj === 'object' && phoneObj.number !== undefined) {
        this.formData.phone = phoneObj.number;
        this.isPhoneValid = phoneObj.valid;
      } else if (phoneObj && typeof phoneObj === 'object' && phoneObj.target) {
        const inputValue = phoneObj.target.value;
        if (inputValue) {
          this.formData.phone = inputValue;
          this.isPhoneValid = inputValue.length >= 7;
        }
      }
      
      // Clean the phone number for storage (remove spaces, dashes, etc.)
      if (this.formData.phone) {
        this.formData.phone = this.formData.phone.replace(/[\s\-()]/g, '');
      }
    },
    validateForm() {
      this.errors = {};
      let isValid = true;
      if (!this.formData.nameEn?.trim()) {
        this.errors.nameEn = this.$t("fieldRequired");
        isValid = false;
      }
      if (!this.formData.nameAr?.trim()) {
        this.errors.nameAr = this.$t("fieldRequired");
        isValid = false;
      }
      if (this.formData.email && !this.isValidEmail(this.formData.email)) {
        this.errors.email = this.$t("invalidEmail");
        isValid = false;
      }
      // Phone validation - more lenient approach
      console.log('Validating phone:', this.formData.phone, 'isPhoneValid:', this.isPhoneValid);
      
      if (!this.formData.phone || this.formData.phone.trim() === '') {
        this.errors.phone = this.$t("invalidPhone");
        isValid = false;
      } else if (this.formData.phone.length < 7) {
        // Minimum length check (country code + at least 6 digits)
        this.errors.phone = this.$t("invalidPhone");
        isValid = false;
      } else {
        // Phone looks valid, clear any existing error
        delete this.errors.phone;
      }
      return isValid;
    },
    getEmptyFormData() {
      return {
        restName: "",
        email: "",
        phone: "",
      };
    },
    isValidEmail(email) {
      const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
      return emailRegex.test(email);
    },
    isValidPhone(phone) {
      // Allow various phone formats including international
      const phoneRegex = /^[+]?[1-9][\d]{0,15}$/;
      return phoneRegex.test(phone.replace(/[\s\-()]/g, ''));
    },
    validateField(field) {
      if (field === "restName" && !this.formData.restName?.trim()) {
        this.errors.restName = this.$t("fieldRequired");
      } else if (field === "email" && this.formData.email && !this.isValidEmail(this.formData.email)) {
        this.errors.email = this.$t("invalidEmail");
      } else if (field === "phone" && this.formData.phone && !this.isValidPhone(this.formData.phone)) {
        this.errors.phone = this.$t("invalidPhone");
      } else {
        delete this.errors[field];
      }
    },
    async submitForm() {
      if (!this.validateForm()) {
        this.toast.error(this.$t("formValidationError"));
        return;
      }
      this.isSubmitting = true;
      try {
        const token = localStorage.getItem("authToken");
        const headers = {
          "Accept-Language": this.$i18n.locale === 'ar' ? 'ar' : 'en',
          Authorization: `Bearer ${token}`,
        };
        const formData = new FormData();
        formData.append('name[en]', this.formData.nameEn);
        formData.append('name[ar]', this.formData.nameAr);
        formData.append('email', this.formData.email);
        
        // Clean phone number - remove spaces, dashes, parentheses, etc.
        const cleanPhone = this.formData.phone ? this.formData.phone.replace(/[\s\-()]/g, '') : '';
        formData.append('phone', cleanPhone);
        let response;
        if (this.type === "edit") {
          // Add _method to form data for Laravel method spoofing
          formData.append('_method', 'PUT');
          response = await axios.post(
            `https://backend.alaqdk.com/api/v1/admin/restaurants/${this.formData.id}`,
            formData,
            { headers }
          );
        } else if (this.type === "add") {
          response = await axios.post(
            "https://backend.alaqdk.com/api/v1/admin/restaurants",
            formData,
            { headers }
          );
        }
        if (response.data.status) {
          this.toast.success(this.type === 'edit' ? this.$t("restaurantUpdated") : this.$t("restaurantAdded"));
          
          // Emit data in the format expected by parent component
          const emitData = {
            id: this.formData.id,
            restName: this.formData.nameEn, // Use English name as display name
            email: this.formData.email,
            phone: this.formData.phone,
            name: {
              en: this.formData.nameEn,
              ar: this.formData.nameAr
            }
          };
          
          console.log('Emitting data to parent:', emitData);
          this.$emit("save", emitData);
        } else {
          this.toast.error(response.data.message || this.$t(this.type === 'edit' ? "updateError" : "addError"));
        }
      } catch (error) {
        this.toast.error(error.response?.data?.message || this.$t(this.type === 'edit' ? "updateError" : "addError"));
      } finally {
        this.isSubmitting = false;
      }
    },
    async confirmApprove() {
      this.isApproving = true;

      try {
        const token = localStorage.getItem("authToken");
        const headers = {
          "Accept-Language": this.$i18n.locale === 'ar' ? 'ar' : 'en',
          Authorization: `Bearer ${token}`,
        };

        const response = await axios.patch(
          `https://backend.alaqdk.com/api/v1/admin/restaurants/${this.formData.id}/approve`,
          { approved: 1 },
          { headers }
        );

        if (response.data.status) {
          this.toast.success(this.$t("approveSuccessMessage"));
          this.$emit("save", { ...this.formData, approved: 1 }); // Emit updated data
        } else {
          this.toast.error(response.data.message || this.$t("approveError"));
        }
      } catch (error) {
        console.error("Approve Error:", error);
        this.toast.error(error.response?.data?.message || this.$t("approveError"));
      } finally {
        this.isApproving = false;
      }
    },
    async confirmDelete() {
      this.isDeleting = true;

      try {
        const token = localStorage.getItem("authToken");
        const headers = {
          "Accept-Language": this.$i18n.locale === 'ar' ? 'ar' : 'en',
          Authorization: `Bearer ${token}`,
        };

        const response = await axios.delete(
          `https://backend.alaqdk.com/api/v1/admin/restaurants/${this.formData.id}`,
          { headers }
        );

        if (response.data.status) {
          this.toast.success(this.$t("deleteSuccessMessage"));
          this.$emit("save", { ...this.formData }); // Emit a copy of the row for deletion
        } else {
          this.toast.error(response.data.message || this.$t("deleteError"));
        }
      } catch (error) {
        console.error("Delete Error:", error);
        this.toast.error(error.response?.data?.message || this.$t("deleteError"));
      } finally {
        this.isDeleting = false;
      }
    },
  },
};
</script>

