<template>
  <div class="home" :dir="$i18n.locale === 'ar' ? 'rtl' : 'ltr'">
    <div class="Control_panel">
      <div class="profile-card">
        <div class="headerCard">
          <div class="image">
            <img
              :src="
                imagePreview ||
                (user.image ? 'https://backend.alaqdk.com/' + user.image + '?t=' + imageTimestamp : null) ||
                require('@/assets/images/profileImage.jpg')
              "
              alt="Profile Picture"
              class="profile-image"
            />
            <input
              id="file-upload"
              type="file"
              accept="image/*"
              @change="handleImageUpload"
              style="opacity: 0; z-index: 2"
              class="inputFile"
            />

            <font-awesome-icon
              :icon="['fas', 'pen-to-square']"
              class="iconEdit"
            />
          </div>
          <div>
            <div class="name">{{ user.name }}</div>
            <div class="email">{{ user.email }}</div>
          </div>
        </div>

        <div class="personal-info">
          <div class="headerContent">
            <div class="section-title">{{ $t("EditInformation") }}</div>
            <button class="addRestbtn" @click="saveProfile" :disabled="isLoading">
              {{ isLoading ? $t("Saving...") : $t("save") }}
            </button>
          </div>
          <div class="info">
            <div class="input-container">
              <label class="label">{{ $t("FullName:") }}:</label>
              <span class="value">
                <input type="text" v-model="user.name" />
              </span>
            </div>
            <div class="input-container">
              <label class="label">{{ $t("email") }}:</label>
              <span class="value">
                <input type="text" v-model="user.email" />
              </span>
            </div>
            <div class="input-container">
              <label class="label">{{ $t("Phone") }}:</label>
              <span class="value">
                <input type="text" v-model="user.phone" />
              </span>
            </div>
          </div>
        </div>
      </div>
    </div>
  </div>
</template>

<script>
// @ is an alias to /src
import { useToast } from 'vue-toastification';
import axios from 'axios';

export default {
  name: "editProfile",
  setup() {
    // Get toast interface
    const toast = useToast();
    return { toast };
  },
  components: {
  },
  data() {
    return {
      // user: {}, // Remove local user
      imagePreview: null,
      isLoading: false,
      selectedImageFile: null, // store the file for upload
      imageTimestamp: Date.now(), // for cache busting
    };
  },
  computed: {
    user() {
      return this.$store.getters.user;
    }
  },
  mounted() {
    console.log(this.user);
  },
  watch: {
    user: {
      handler(newUser) {
        console.log("User data changed:", newUser);
      },
      deep: true
    }
  },
  methods: {
    // handleUserData(userData) { // Remove this method
    //   this.user = userData;
    // },
    handleImageUpload(event) {
      const file = event.target.files[0];
      if (file) {
        this.imagePreview = URL.createObjectURL(file); // for preview
        this.selectedImageFile = file; // store the file for upload
      }
    },
    async saveProfile() {
      console.log("saveProfile method called");
      
      // Simple validation
      if (!this.user.name || !this.user.email || !this.user.phone) {
        this.toast.error(this.$t("Please fill in all fields"));
        return;
      }

      // Email validation
      const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
      if (!emailPattern.test(this.user.email)) {
        this.toast.error(this.$t("Please enter a valid email address"));
        return;
      }

      // Phone number validation (example: must be numeric and 10 digits)
      const phonePattern = /^\d{10}$/;
      if (!phonePattern.test(this.user.phone)) {
        this.toast.error(this.$t("Please enter a valid phone number (10 digits)"));
        return;
      }

      this.isLoading = true;
      
      try {
        console.log('Starting profile update...');
        console.log('User data:', this.user);
        
        const formData = new FormData();
        formData.append('name', this.user.name);
        formData.append('email', this.user.email);
        formData.append('phone', this.user.phone);
        if (this.selectedImageFile) {
          formData.append('image', this.selectedImageFile);
        }
        formData.append('_method', 'put'); // <-- Laravel expects this for file uploads
        
        console.log('Profile data to send:', formData);
        
        // Log the FormData contents for debugging
        for (let [key, value] of formData.entries()) {
          console.log(`${key}:`, value);
        }

        // Make API call to update profile
        const response = await axios.post('https://backend.alaqdk.com/api/v1/admin/update-profile', formData, {
          headers: {
            'Authorization': 'Bearer ' + localStorage.getItem("authToken"),
            // Do NOT set Content-Type, browser will set it for FormData
          }
        });
        
        if (response.data.status) {
          this.toast.success(this.$t("Profile updated successfully"));
          
          // Log the full response for debugging
          console.log("Full response:", response.data);
          
          // Update the store with the new user data from response.data.data
          const updatedUser = response.data.data || this.user;
          this.$store.dispatch('setUser', updatedUser);
          
          // If we uploaded a new image, clear the local preview and selected file
          if (this.selectedImageFile) {
            this.imagePreview = null;
            this.selectedImageFile = null;
            // Update timestamp to force image reload
            this.imageTimestamp = Date.now();
            console.log("Updated user data:", updatedUser);
            console.log("New image URL:", updatedUser.image);
            console.log("Image field in response:", response.data.data?.image);
          }
          
          console.log("Profile updated successfully:", response.data);
        } else {
          this.toast.error(response.data.message || this.$t("Failed to update profile"));
        }
      } catch (error) {
        console.error("Error updating profile:", error);
        
        if (error.response) {
          // Server responded with error status
          const errorMessage = error.response.data?.message || this.$t("Failed to update profile");
          this.toast.error(errorMessage);
        } else if (error.request) {
          // Network error
          this.toast.error(this.$t("Network error. Please check your connection."));
        } else {
          // Other error
          this.toast.error(this.$t("An unexpected error occurred"));
        }
      } finally {
        this.isLoading = false;
      }
    },
  },
};
</script>
