<template>
  <div class="home" :dir="$i18n.locale === 'ar' ? 'rtl' : 'ltr'">
    <div class="Control_panel">
      <div class="table-container">
        <div class="headerTable">
          <div class="icon_text">
            <div class="icon">
              <SvgIcon name="resturant"></SvgIcon>
            </div>
            <p>{{ $t("AllNotifications") }}</p>
          </div>
          <div class="search_add">
            <div class="search">
              <input type="text" v-model="filter" :placeholder="$t('search')" />
              <SvgIcon class="svg" name="search"></SvgIcon>
            </div>
            <button class="search-button" @click="openPopup('add', {})">
              <p class="addRestbtn">{{ $t("AddNotifi") }}</p>
              <span class="icon">
                <SvgIcon name="add"></SvgIcon>
              </span>
            </button>
          </div>
        </div>
        
        <!-- Loading state -->
        <div v-if="loading" class="loading-container">
          <div class="loading-spinner"></div>
          <p>{{ $t("Loading") }}</p>
        </div>
        
        <!-- Error state -->
        <div v-else-if="error" class="error-container">
          <p>{{ error }}</p>
          <button @click="fetchNotifications" class="retry-button">
            {{ $t("Retry") }}
          </button>
        </div>
        
        <!-- Data table -->
        <div v-else class="table-responsive">
          <table>
            <thead>
              <tr class="table-header">
                <th>
                  <div
                    style="
                      display: flex;
                      align-items: center;
                      margin-right: 10px;
                      gap: 5px;
                    "
                  >
                    <SvgIcon name="circle"></SvgIcon>
                    {{ $t("headTable1") }}
                  </div>
                </th>
                <th>{{ $t("head9Table2") }}</th>
                <th>{{ $t("head9Table3") }}</th>
                <th>{{ $t("head9Table4") }}</th>
                <th>{{ $t("head9Table5") }}</th>
                <th>{{ $t("head9Table6") }}</th>
                <th>{{ $t("head4Table7") }}</th>
                <th>{{ $t("AllProcedures") }}</th>
              </tr>
            </thead>
            <tbody>
              <tr
                v-for="notification in filteredNotifications"
                :key="`notification-${notification.id}`"
              >
                <td
                  style="
                    display: flex;
                    align-items: center;
                    margin-right: 10px;
                    gap: 5px;
                  "
                >
                  <SvgIcon name="dot_circle"></SvgIcon>
                  {{ notification.id }}
                </td>
                <td>
                  <img 
                    v-if="notification.image" 
                    :src="notification.image" 
                    :alt="notification.title"
                    class="notification-image"
                  />
                  <span v-else>{{ $t("NoImage") }}</span>
                </td>
                <td>{{ notification.title }}</td>
                <td>{{ notification.body }}</td>
                <td>{{ notification.user?.name || $t("UnknownUser") }}</td>
                <td>
                  {{ notification.user?.email || $t("NoEmail") }}
                </td>
                <td>
                  <label class="switch">
                    <input
                      type="checkbox"
                      :checked="!notification.is_read"
                      @change="updateReadStatus(notification)"
                    />
                    <span class="slider round"></span>
                  </label>
                </td>
                <td class="actions">
                  <div class="iconsIctions">
                    <div class="icon" @click="openPopup('edit', notification)">
                      <SvgIcon class="svg" name="edit"></SvgIcon>
                    </div>
                    <div class="icon" @click="openPopup('delete', notification)">
                      <SvgIcon class="svg delete" name="deleteItem"></SvgIcon>
                    </div>
                  </div>
                </td>
              </tr>
            </tbody>
          </table>
          
          <!-- Empty state -->
          <div v-if="filteredNotifications.length === 0 && !loading" class="empty-state">
            <p>{{ $t("NoNotificationsFound") }}</p>
          </div>
        </div>
      </div>
    </div>
  </div>
  <notification-popup
    v-if="popupData.visible"
    :type="popupData.type"
    :data="popupData.row"
    @close="closePopup"
    @save="handleSave"
  />
</template>

<script>
// @ is an alias to /src
import NotificationPopup from "@/components/dashboard/popus/notificationPopup.vue";
import SvgIcon from "@/components/SvgIcon.vue";
import axios from "@/axios.js";
import { useToast } from "vue-toastification";

export default {
  name: "SendNotifications",
  components: {
    NotificationPopup,
    SvgIcon,
  },
  setup() {
    const toast = useToast();
    return { toast };
  },
  data() {
    return {
      filter: "",
      notifications: [],
      loading: false,
      error: null,
      popupData: {
        visible: false,
        type: "",
        row: null,
      },
    };
  },
  computed: {
    filteredNotifications() {
      return this.notifications.filter((notification) => {
        if (!this.filter) return true;
        const searchTerm = this.filter.toLowerCase();
        return (
          (notification.title && notification.title.toLowerCase().includes(searchTerm)) ||
          (notification.body && notification.body.toLowerCase().includes(searchTerm)) ||
          (notification.user?.name && notification.user.name.toLowerCase().includes(searchTerm)) ||
          (notification.user?.email && notification.user.email.toLowerCase().includes(searchTerm))
        );
      });
    },
  },
  async mounted() {
    await this.fetchNotifications();
  },
  methods: {
    async fetchNotifications() {
      this.loading = true;
      this.error = null;
      
      try {
        const token = localStorage.getItem("authToken");
        const response = await axios.get("v1/admin/notifications", {
          headers: {
            "Accept-Language": this.$i18n.locale,
            Authorization: `Bearer ${token}`,
          },
        });
        
        if (response.data.status) {
          this.notifications = response.data.data;
          this.toast.success(this.$t("NotificationsLoadedSuccessfully"));
        } else {
          this.error = response.data.message || this.$t("FailedToLoadNotifications");
          this.toast.error(this.error);
        }
      } catch (error) {
        console.error("Error fetching notifications:", error);
        this.error = error.response?.data?.message || this.$t("FailedToLoadNotifications");
        this.toast.error(this.error);
      } finally {
        this.loading = false;
      }
    },
    
    async updateReadStatus(notification) {
      try {
        const token = localStorage.getItem("authToken");
        const response = await axios.put(`v1/admin/notifications/${notification.id}/read-status`, {
          is_read: !notification.is_read
        }, {
          headers: {
            "Accept-Language": this.$i18n.locale,
            Authorization: `Bearer ${token}`,
          },
        });
        
        if (response.data.status) {
          // Update the local notification data
          const index = this.notifications.findIndex(n => n.id === notification.id);
          if (index !== -1) {
            this.notifications[index].is_read = !notification.is_read;
          }
          this.toast.success(this.$t("StatusUpdatedSuccessfully"));
        } else {
          this.toast.error(response.data.message || this.$t("FailedToUpdateStatus"));
        }
      } catch (error) {
        console.error("Error updating read status:", error);
        this.toast.error(this.$t("FailedToUpdateStatus"));
      }
    },

    async deleteNotification(notificationId) {
      try {
        const token = localStorage.getItem("authToken");
        const response = await axios.delete(
          `v1/admin/notifications/${notificationId}`,
          {
            headers: {
              "Accept-Language": this.$i18n.locale,
              Authorization: `Bearer ${token}`,
            },
          }
        );
        if (response.data.status) {
          this.toast.success(this.$t("Notification deleted successfully!"));
          await this.fetchNotifications();
        } else {
          this.toast.error(response.data.message || this.$t("OperationFailed"));
        }
      } catch (error) {
        console.error("Error deleting notification:", error);
        this.toast.error(this.$t("OperationFailed"));
      }
    },
    
    openPopup(type, notification) {
      this.popupData = {
        visible: true,
        type,
        row: notification,
      };
    },
    
    closePopup() {
      this.popupData.visible = false;
    },
    
    async handleSave(updatedNotification) {
      try {
        const token = localStorage.getItem("authToken");
        let response;
        
        if (this.popupData.type === "add") {
          // Use FormData for push notification
          const formData = new FormData();
          formData.append('header', updatedNotification.header);
          formData.append('body', updatedNotification.body);
          if (updatedNotification.user_role) {
            formData.append('user_role', updatedNotification.user_role);
          }
          if (updatedNotification.image instanceof File) {
            formData.append('image', updatedNotification.image);
          }
          if (Array.isArray(updatedNotification.users)) {
            updatedNotification.users.forEach((userId, idx) => {
              formData.append(`users[${idx}]`, userId);
            });
          }
          response = await axios.post(
            "v1/admin/notifications/push-notification",
            formData,
            {
              headers: {
                "Accept-Language": this.$i18n.locale,
                Authorization: `Bearer ${token}`,
                "Content-Type": "multipart/form-data",
              },
            }
          );
        } else if (this.popupData.type === "edit") {
          // Use FormData for method spoofing
          const formData = new FormData();
          formData.append('_method', 'put');
          formData.append('title', updatedNotification.title);
          formData.append('body', updatedNotification.body);
          formData.append('user_id', updatedNotification.user_id);
          if (updatedNotification.order_id) {
            formData.append('order_id', updatedNotification.order_id);
          }
          // If you have an image and it's a File:
          // if (updatedNotification.image instanceof File) {
          //   formData.append('image', updatedNotification.image);
          // }

          response = await axios.post(
            `v1/admin/notifications/${updatedNotification.id}`,
            formData,
            {
              headers: {
                "Accept-Language": this.$i18n.locale,
                Authorization: `Bearer ${token}`,
                "Content-Type": "multipart/form-data",
              },
            }
          );
        } else if (this.popupData.type === "delete") {
          // Handle delete operation
          response = await axios.delete(
            `v1/admin/notifications/${updatedNotification.id}`,
            {
              headers: {
                "Accept-Language": this.$i18n.locale,
                Authorization: `Bearer ${token}`,
              },
            }
          );
        }
        
        if (response.data.status) {
          this.toast.success(this.$t("OperationCompletedSuccessfully"));
          // Refresh the notifications list
          await this.fetchNotifications();
        } else {
          this.toast.error(response.data.message || this.$t("OperationFailed"));
        }
      } catch (error) {
        console.error("Error saving notification:", error);
        this.toast.error(this.$t("OperationFailed"));
      }
      
      this.closePopup();
    },
  },
};
</script>
