/* Custom Toggle Switch for 24x14px */
.switch {
  position: relative;
  display: inline-block;
  width: 24px;
  height: 14px;
  top: 5px;
}

.switch input {
  opacity: 0;
  width: 0;
  height: 0;
}

.slider {
  position: absolute;
  cursor: pointer;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background: #ccc;
  opacity: 1;
  border-radius: 100px;
  transition: background 0.3s;
}

.slider:before {
  position: absolute;
  content: "";
  height: 12px;
  width: 12px;
  left: 1px;
  bottom: 1px;
  background: #fff;
  transition: 0.3s;
  border-radius: 50%;
}

input:checked + .slider {
  background: #3FAD4C;
}

input:checked + .slider:before {
  transform: translateX(10px);
}

/* Loading, Error, and Empty States */
.loading-container,
.error-container,
.empty-state {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 40px 20px;
  text-align: center;
  min-height: 200px;
}

.loading-spinner {
  width: 40px;
  height: 40px;
  border: 4px solid #f3f3f3;
  border-top: 4px solid #5c0e35;
  border-radius: 50%;
  animation: spin 1s linear infinite;
  margin-bottom: 16px;
}

@keyframes spin {
  0% { transform: rotate(0deg); }
  100% { transform: rotate(360deg); }
}

.error-container p {
  color: #d32f2f;
  margin-bottom: 16px;
  font-size: 16px;
}

.retry-button {
  background-color: #5c0e35;
  color: white;
  border: none;
  padding: 10px 20px;
  border-radius: 8px;
  cursor: pointer;
  font-family: Almarai !important;
  transition: background-color 0.3s;
}

.retry-button:hover {
  background-color: #4a0b2a;
}

.empty-state p {
  color: #666;
  font-size: 16px;
  margin: 0;
}

/* Notification Image Styles */
.notification-image {
  width: 40px;
  height: 40px;
  object-fit: cover;
  border-radius: 8px;
  border: 1px solid #e0e0e0;
}
