<template>
  <div class="home" :dir="$i18n.locale === 'ar' ? 'rtl' : 'ltr'">
    <div class="Control_panel">
      <div class="profile-card">
        <div class="personal-info">
          <div class="headerContent">
            <div class="section-title">{{ $t("ChangePassword") }}</div>
            <button class="addRestbtn" @click="submitForm">{{ $t("save") }}</button>
          </div>
          <div class="info">
            <div class="input-container">
              <label class="label">{{ $t("oldPassword") }}</label>
              <span class="value">
                <input :type="showOldPassword ? 'text' : 'password'" v-model="oldPassword" @input="v$.oldPassword.$touch()" />
                <button type="button" @click="toggleShowOldPassword" class="show-hide-btn">
                  <i :class="showOldPassword ? 'fa-solid fa-eye-slash' : 'fa-solid fa-eye'"></i>
                </button>
              </span>
              <div v-if="oldPasswordError" class="error-message">{{ oldPasswordError }}</div>
            </div>
            <div class="input-container">
              <label class="label">{{ $t("newPassword") }}</label>
              <span class="value">
                <input :type="showNewPassword ? 'text' : 'password'" v-model="newPassword" @input="v$.newPassword.$touch()" />
                <button type="button" @click="toggleShowNewPassword" class="show-hide-btn">
                  <i :class="showNewPassword ? 'fa-solid fa-eye-slash' : 'fa-solid fa-eye'"></i>
                </button>
              </span>
              <div v-if="newPasswordError" class="error-message">{{ newPasswordError }}</div>
            </div>
            <div class="input-container">
              <label class="label">{{ $t("confirmPassword") }}</label>
              <span class="value">
                <input :type="showConfirmPassword ? 'text' : 'password'" v-model="confirmPassword" @input="v$.confirmPassword.$touch()" />
                <button type="button" @click="toggleShowConfirmPassword" class="show-hide-btn">
                  <i :class="showConfirmPassword ? 'fa-solid fa-eye-slash' : 'fa-solid fa-eye'"></i>
                </button>
              </span>
              <div v-if="confirmPasswordError" class="error-message">{{ confirmPasswordError }}</div>
            </div>
          </div>
        </div>
      </div>
    </div>
  </div>
</template>

<script>

import { useToast } from "vue-toastification";
import useVuelidate from "@vuelidate/core";
import { required, sameAs, minLength } from "@vuelidate/validators";
import axiosInstance from "../axios.js";

export default {
  name: "forgetPassword",
  components: {

  },
  setup() {
    const toast = useToast();
    return { v$: useVuelidate(), toast };
  },
  data() {
    return {
      oldPassword: "",
      newPassword: "",
      confirmPassword: "",
      showOldPassword: false,
      showNewPassword: false,
      showConfirmPassword: false,
    };
  },
  validations() {
    return {
      oldPassword: { required },
      newPassword: {
        required,
        minLength: minLength(6)
      },
      confirmPassword: {
        required,
        sameAs: sameAs(this.newPassword)
      }
    };
  },
  computed: {
    user() {
      return this.$store.getters.user;
    },
    oldPasswordError() {
      const v = this.v$.oldPassword;
      if (!v.$dirty) return "";
      if (!v.required) return this.$t("oldPassword") + " is required";
      return "";
    },
    newPasswordError() {
      const v = this.v$.newPassword;
      if (!v.$dirty) return "";
      if (!v.required) return this.$t("newPassword") + " is required";
      if (!v.minLength) return this.$t("newPassword") + " must be at least 6 characters";
      return "";
    },
    confirmPasswordError() {
      const v = this.v$.confirmPassword;
      if (!v.$dirty) return "";
      if (!v.required) return this.$t("confirmPassword") + " is required";
      if (!v.sameAs) return this.$t("confirmPassword") + " does not match";
      return "";
    }
  },
  mounted() {
    // console.log(this.user); // Remove this line since user is now from Vuex
  },
  methods: {
    toggleShowOldPassword() {
      this.showOldPassword = !this.showOldPassword;
    },
    toggleShowNewPassword() {
      this.showNewPassword = !this.showNewPassword;
    },
    toggleShowConfirmPassword() {
      this.showConfirmPassword = !this.showConfirmPassword;
    },
    async submitForm() {
      this.v$.$touch();
      const isFormValid = await this.v$.$validate();
      if (!isFormValid) {
        this.toast.error("Please fill all fields correctly");
        return;
      }
      try {
        await axiosInstance.post('v1/admin/change-old-password', {
          old_password: this.oldPassword,
          password: this.newPassword,
          password_confirmation: this.confirmPassword
        });
        this.toast.success("Password changed successfully!");
        this.oldPassword = "";
        this.newPassword = "";
        this.confirmPassword = "";
        this.v$.$reset();
      } catch (error) {
        if (error.response && error.response.data && error.response.data.message) {
          this.toast.error(error.response.data.message);
        } else {
          this.toast.error("Failed to change password. Please try again.");
        }
      }
    }
  },
};
</script>
