<template>
  <div class="home" :dir="$i18n.locale === 'ar' ? 'rtl' : 'ltr'">
    <div class="Control_panel">
      <div class="boxDetails">
        <boxDetails />
      </div>
      <div class="dashboard">
        <div class="summary-container">
          <p>{{ $t("OrderPlanner") }}</p>
          <div class="order-summary">
            <span class="order-count">{{ totalOrders.toLocaleString() }}</span>
            <span class="order-percentage">{{ orderPercentageChange }}</span>
            <button class="refresh-btn" @click="refreshOrderData" title="Refresh Order Data" :disabled="isOrderDataLoading">
              <SvgIcon :name="isOrderDataLoading ? 'loading' : 'refresh'" :class="{ 'rotating': isOrderDataLoading }"></SvgIcon>
            </button>
          </div>
          <canvas id="orders-chart"></canvas>
          <div class="month-selector">
            <span>{{ $t('jan') }}</span>
            <span>{{ $t('feb') }}</span>
            <span class="active">{{ $t('march') }}</span>
            <span>{{ $t('apr') }}</span>
            <span>{{ $t('may') }}</span>
          </div>
        </div>
        <div class="chart-container">
          <div class="Flex">
            <p>{{ $t("Sales_purchase") }}</p>
            <div class="legend">
              <span><span class="sales-dot"></span> {{ $t("Sales") }}</span>
              <button class="refresh-btn" @click="refreshSalesData" title="Refresh Sales Data" :disabled="isSalesDataLoading">
                <SvgIcon :name="isSalesDataLoading ? 'loading' : 'refresh'" :class="{ 'rotating': isSalesDataLoading }"></SvgIcon>
              </button>
            </div>
          </div>
          <canvas id="sales-purchases-chart"></canvas>
        </div>
      </div>
      <div class="table-container">
        <div class="headerTable">
          <div class="icon_text">
            <div class="icon">
              <SvgIcon name="resturant"></SvgIcon>
            </div>
            <p>{{ $t("restuarants") }}</p>
          </div>
          <div class="search_add">
            <div class="search">
              <input type="text" v-model="filter" :placeholder="$t('search')" />
              <SvgIcon class="svg" name="search"></SvgIcon>
            </div>
            <button class="search-button" @click="openPopup('add', {})">
              <p class="addRestbtn">{{ $t("AddRest") }}</p>
              <span class="icon">
                <SvgIcon name="add"></SvgIcon>
              </span>
            </button>
          </div>
        </div>
        <LoadingHere :isLoading="isLoading" />

        <div class="table-responsive">
          <table>
            <thead>
              <tr class="table-header">
                <th>
                  <div
                    style="
                      display: flex;
                      align-items: center;
                      margin-right: 10px;
                      gap: 5px;
                    "
                  >
                    <SvgIcon name="circle"></SvgIcon>

                    {{ $t("headTable1") }}
                  </div>
                </th>
                <th>{{ $t("headTable2") }}</th>
                <th>{{ $t("headTable3") }}</th>
                <th>{{ $t("headTable4") }}</th>
                <th>{{ $t("headTable5") }}</th>
                <th>{{ $t("AllProcedures") }}</th>
              </tr>
            </thead>
            <tbody>
              <tr
                v-for="(rows, index) in filteredRows"
                :key="`product-${index}`"
              >
                <td
                  style="
                    display: flex;
                    align-items: center;
                    margin-right: 10px;
                    gap: 5px;
                  "
                >
                  <SvgIcon name="dot_circle"></SvgIcon>
                  {{ rows.id }}
                </td>
                <td>{{ rows.restName }}</td>
                <td>{{ rows.productCount }}</td>
                <td>{{ rows.orderCount }}</td>
                <td>{{ formatDate(rows.lastPurchase) }}</td>
                <td class="actions">
                  <div class="iconsIctions">
                    <div class="icon" @click="openPopup('edit', rows)">
                      <SvgIcon class="svg" name="edit"></SvgIcon>
                    </div>
                    <div class="icon" @click="openPopup('view', rows)">
                      <SvgIcon class="svg" name="view"></SvgIcon>
                    </div>
                    <div class="icon" @click="openPopup('delete', rows)">
                      <SvgIcon class="svg delete" name="deleteItem"></SvgIcon>
                    </div>
                  </div>
                </td>
              </tr>
            </tbody>
          </table>
        </div>
      </div>
    </div>
  </div>
  <dashboardPopup
    v-if="isPopupVisible"
    :type="popupType"
    :row="selectedRow"
    @close="closePopup"
    @save="handlePopupSave"
  />
</template>

<script>
// @ is an alias to /src
import boxDetails from "@/components/dashboard/boxDetails.vue";
import { Chart, registerables } from "chart.js";
import DashboardPopup from "@/components/dashboard/popus/dashboardPopup.vue";
import LoadingHere from "@/components/LoadingHere.vue";
import axios from "axios";
import SvgIcon from "@/components/SvgIcon.vue";
import { getLocalizedNameWithI18n } from "@/utils/localization.js";

// Register all Chart.js components
Chart.register(...registerables);

export default {
  name: "dashboardHome",
  components: {
    boxDetails,
    LoadingHere,
    DashboardPopup,
    SvgIcon,
  },

  data() {
    return {
      filter: "",
      rows: [
        // More products here
      ],
      isPopupVisible: false,
      popupType: "",
      selectedRow: {},
      isLoading: false,
      salesChart: null,
      ordersChart: null,
      resizeTimeout: null,
      chartsInitialized: false,
      salesChartData: {
        labels: [],
        sales: [],
        purchases: []
      },
      orderChartData: {
        labels: [],
        orders: []
      },
      isSalesDataLoading: false,
      isOrderDataLoading: false,
    };
  },
  computed: {
    filteredRows() {
      return this.rows.filter((row) => {
        const searchTerm = this.filter.toLowerCase();
        return (
          (typeof row.restName === "string" &&
            row.restName.toLowerCase().includes(searchTerm)) ||
          (row.id && row.id.toString().toLowerCase().includes(searchTerm))
        );
      });
    },
    totalSales() {
      return this.salesChartData.sales.reduce((sum, sale) => sum + sale, 0);
    },
    salesPercentageChange() {
      if (this.salesChartData.sales.length < 2) return "+0%";
      
      const currentPeriod = this.salesChartData.sales.slice(-3).reduce((sum, sale) => sum + sale, 0);
      const previousPeriod = this.salesChartData.sales.slice(-6, -3).reduce((sum, sale) => sum + sale, 0);
      
      if (previousPeriod === 0) return "+0%";
      
      const change = ((currentPeriod - previousPeriod) / previousPeriod) * 100;
      return `${change >= 0 ? '+' : ''}${Math.round(change)}%`;
    },
    totalOrders() {
      return this.orderChartData.orders.reduce((sum, order) => sum + order, 0);
    },
    orderPercentageChange() {
      if (this.orderChartData.orders.length < 2) return "+0%";
      
      const currentPeriod = this.orderChartData.orders.slice(-3).reduce((sum, order) => sum + order, 0);
      const previousPeriod = this.orderChartData.orders.slice(-6, -3).reduce((sum, order) => sum + order, 0);
      
      if (previousPeriod === 0) return "+0%";
      
      const change = ((currentPeriod - previousPeriod) / previousPeriod) * 100;
      return `${change >= 0 ? '+' : ''}${Math.round(change)}%`;
    },
  },
      async mounted() {
      this.isLoading = true;
      this.fetchUserData(); // Fetch user data dynamically
      this.FetchRows(); // Fetch rows dynamically
      this.fetchSalesChartData(); // Fetch sales chart data
      this.fetchOrderChartData(); // Fetch order chart data

      // Wait for DOM to be ready and ensure canvas elements exist
      await this.$nextTick();
      
      // Additional wait to ensure DOM is fully rendered
      await new Promise(resolve => setTimeout(resolve, 200));
    
    // Test Chart.js availability
    if (typeof Chart === 'undefined') {
      console.error('Chart.js is not available. Please check the import.');
      return;
    }
    
    // Add global error handler for Chart.js
    this.addChartErrorHandler();
    
    // Initialize charts with proper error handling
    this.initializeCharts();
    
    // Retry chart initialization if it fails
    setTimeout(() => {
      if (!this.chartsInitialized) {
        console.log('Retrying chart initialization...');
        this.initializeCharts();
      }
    }, 1000);
    
    if (this.$toast) {
      this.$toast.success("Welcome to your dashboard!");
    }
    
    // Add resize listener for responsive charts
    window.addEventListener('resize', this.handleResize);
  },
  beforeUnmount() {
    // Clean up charts to prevent memory leaks
    this.destroyCharts();
    
    // Remove resize listener
    window.removeEventListener('resize', this.handleResize);
    
    // Clear any remaining timeouts
    if (this.resizeTimeout) {
      clearTimeout(this.resizeTimeout);
    }
  },
  methods: {
    addChartErrorHandler() {
      // Add global error handler for Chart.js context issues
      const originalError = console.error;
      console.error = (...args) => {
        const errorMessage = args.join(' ');
        if (errorMessage.includes('Cannot read properties of null') && 
            errorMessage.includes('save')) {
          console.warn('Chart.js context error detected and handled:', errorMessage);
          return;
        }
        originalError.apply(console, args);
      };
    },
    destroyCharts() {
      try {
        if (this.salesChart) {
          this.salesChart.destroy();
          this.salesChart = null;
        }
        if (this.ordersChart) {
          this.ordersChart.destroy();
          this.ordersChart = null;
        }
        this.chartsInitialized = false;
      } catch (error) {
        console.error("Error destroying charts:", error);
      }
    },
    initializeCharts() {
      try {
        if (this.chartsInitialized) {
          return;
        }
        
        // Check if Chart is properly imported
        if (typeof Chart === 'undefined') {
          console.error('Chart is not defined. Chart.js may not be properly imported.');
          return;
        }
        
        // Ensure Chart.js is fully loaded
        if (!Chart.prototype || !Chart.prototype.constructor) {
          console.error('Chart.js is not properly initialized');
          return;
        }
        
        // Check if canvas elements exist
        const salesCanvas = document.getElementById("sales-purchases-chart");
        const ordersCanvas = document.getElementById("orders-chart");
        
        if (!salesCanvas || !ordersCanvas) {
          console.log('Canvas elements not found, retrying in 500ms...');
          setTimeout(() => this.initializeCharts(), 500);
          return;
        }
        
        // Render charts with fallback data if needed
        this.renderSalesPurchasesChart();
        this.renderOrdersChart();
        this.chartsInitialized = true;
        console.log('Charts initialized successfully');
        
      } catch (error) {
        console.error("Error initializing charts:", error);
        // Reset initialization flag to allow retry
        this.chartsInitialized = false;
      }
    },
    handleResize() {
      // Debounce resize events for better performance
      clearTimeout(this.resizeTimeout);
      this.resizeTimeout = setTimeout(() => {
        try {
          if (this.salesChart && this.salesChart.canvas && typeof this.salesChart.resize === 'function') {
            this.salesChart.resize();
          }
          if (this.ordersChart && this.ordersChart.canvas && typeof this.ordersChart.resize === 'function') {
            this.ordersChart.resize();
          }
        } catch (error) {
          console.error("Error resizing charts:", error);
        }
      }, 250);
    },
    fetchUserData() {
      // Simulate fetching user data from an API or store
    },
    fetchSalesChartData() {
      this.isSalesDataLoading = true;
      const token = localStorage.getItem("authToken");
      axios
        .get(
          "https://backend.alaqdk.com/api/v1/admin/dashboard/get-sales-chart",
          {
            headers: {
              "Accept-Language": "ar",
              Authorization: `Bearer ${token}`,
            },
          }
        )
        .then((response) => {
          this.isSalesDataLoading = false;
          console.log("Sales Chart Response:", response.data);
          const data = response.data;
          
          if (data && data.status && data.data && Array.isArray(data.data)) {
            // Process the sales data
            this.salesChartData.labels = data.data.map(item => {
              // Format date for display (e.g., "Jun 10", "Jun 15")
              const date = new Date(item.date);
              return date.toLocaleDateString('en-US', { 
                month: 'short', 
                day: 'numeric' 
              });
            }).filter(label => label && label !== 'Invalid Date'); // Filter out invalid dates
            
            this.salesChartData.sales = data.data.map(item => {
              const total = item.total || 0;
              return typeof total === 'number' && !isNaN(total) ? total : 0;
            });
            
            // For now, we'll use the same data for purchases since the API only returns sales
            // In the future, you might want to add a separate API call for purchases
            this.salesChartData.purchases = data.data.map(item => {
              const total = item.total || 0;
              const purchaseValue = Math.floor((total * 0.7));
              return typeof purchaseValue === 'number' && !isNaN(purchaseValue) ? purchaseValue : 0;
            });
            
            console.log("Processed sales chart data:", this.salesChartData);
            
            // Ensure all arrays have the same length
            this.synchronizeChartData();
            
            // Re-render the sales chart with new data
            if (this.chartsInitialized) {
              this.renderSalesPurchasesChart();
            }
            
            // Show success message
            if (this.$toast) {
              this.$toast.success("Sales data updated successfully!");
            }
          } else {
            console.error("Failed to fetch sales chart data: Invalid data structure", data);
            if (this.$toast) {
              this.$toast.error("Failed to load sales data");
            }
          }
        })
        .catch((error) => {
          this.isSalesDataLoading = false;
          console.error("Error fetching sales chart data:", error);
          // Use fallback data if API fails
          this.salesChartData = {
            labels: ["Jun 10", "Jun 15", "Jun 20", "Jun 25", "Jun 30", "Jul 5", "Jul 10"],
            sales: [0, 0, 0, 0, 0, 0, 0],
            purchases: [0, 0, 0, 0, 0, 0, 0]
          };
          
          if (this.$toast) {
            this.$toast.error("Failed to load sales data. Using fallback data.");
          }
        });
    },
    fetchOrderChartData() {
      this.isOrderDataLoading = true;
      const token = localStorage.getItem("authToken");
      axios
        .get(
          "https://backend.alaqdk.com/api/v1/admin/dashboard/get-order-count",
          {
            headers: {
              "Accept-Language": "ar",
              Authorization: `Bearer ${token}`,
            },
          }
        )
        .then((response) => {
          this.isOrderDataLoading = false;
          console.log("Order Chart Response:", response.data);
          const data = response.data;
          
          if (data && data.status && data.data && Array.isArray(data.data)) {
            // Process the order data
            this.orderChartData.labels = data.data.map(item => {
              // Format date for display (e.g., "Jan 10", "Jan 15")
              const date = new Date(item.date);
              return date.toLocaleDateString('en-US', { 
                month: 'short', 
                day: 'numeric' 
              });
            }).filter(label => label && label !== 'Invalid Date'); // Filter out invalid dates
            
            this.orderChartData.orders = data.data.map(item => {
              const totalOrders = item.total_orders || 0;
              return typeof totalOrders === 'number' && !isNaN(totalOrders) ? totalOrders : 0;
            });
            
            console.log("Processed order chart data:", this.orderChartData);
            
            // Re-render the orders chart with new data
            if (this.chartsInitialized) {
              this.renderOrdersChart();
            }
            
            // Show success message
            if (this.$toast) {
              this.$toast.success("Order data updated successfully!");
            }
          } else {
            console.error("Failed to fetch order chart data: Invalid data structure", data);
            if (this.$toast) {
              this.$toast.error("Failed to load order data");
            }
          }
        })
        .catch((error) => {
          this.isOrderDataLoading = false;
          console.error("Error fetching order chart data:", error);
          // Use fallback data if API fails
          this.orderChartData = {
            labels: ["Jan", "Feb", "March", "Apr", "May"],
            orders: [10000, 11000, 11756, 10500, 11200]
          };
          
          if (this.$toast) {
            this.$toast.error("Failed to load order data. Using fallback data.");
          }
        });
    },
    refreshSalesData() {
      console.log("Refreshing sales data...");
      this.fetchSalesChartData();
    },
    refreshOrderData() {
      console.log("Refreshing order data...");
      this.fetchOrderChartData();
    },
    FetchRows() {
      const token = localStorage.getItem("authToken");
      axios
        .get(
          "https://backend.alaqdk.com/api/v1/admin/restaurants",
          {
            headers: {
              "Accept-Language": "ar",
              Authorization: `Bearer ${token}`, // Add the Authorization header
            },
          }
        )
        .then((response) => {
          this.isLoading = false;
          console.log("Restaurant Response:", response.data); // Log the response
          const data = response.data;
          
          // Check if data exists and has the expected structure
          if (data && data.status && data.data && Array.isArray(data.data)) {
            this.rows = data.data
              .filter((item) => item && item.id) // Filter out items without id
              .map((item) => ({
                id: item.id || `restaurant_${Date.now()}_${Math.random()}`,
                restName: getLocalizedNameWithI18n(item.name, this.$i18n) || "N/A",
                email: item.email || "",
                phone: item.phone || "",
                productCount: item.total_products || 0,
                orderCount: item.total_orders || 0,
                lastPurchase: item.last_order || "No orders yet",
              }));
            console.log("Processed rows:", this.rows);
          } else {
            console.error("Failed to fetch rows data: Invalid data structure", data);
            this.rows = []; // Set empty array if data is invalid
          }
        })
        .catch((error) => {
          this.isLoading = false; // Set loading state to false
          console.error("Error fetching rows data:", error);
          this.rows = []; // Set empty array on error
        });
    },
    renderSalesPurchasesChart() {
      try {
        const canvas = document.getElementById("sales-purchases-chart");
        if (!canvas) {
          console.warn("Sales chart canvas not found");
          return;
        }
        
        // Check if canvas is still in the DOM
        if (!document.contains(canvas)) {
          console.warn("Sales chart canvas is not in the DOM");
          return;
        }
        
        // Destroy existing chart if it exists
        if (this.salesChart) {
          try {
            this.salesChart.destroy();
          } catch (destroyError) {
            console.warn("Error destroying sales chart:", destroyError);
          }
          this.salesChart = null;
        }
        
        // Ensure canvas has proper dimensions before getting context
        if (canvas.width === 0 || canvas.height === 0) {
          canvas.width = canvas.offsetWidth || 400;
          canvas.height = canvas.offsetHeight || 200;
        }
        
        // Additional check to ensure canvas is properly sized
        if (canvas.offsetWidth === 0 || canvas.offsetHeight === 0) {
          canvas.style.width = '400px';
          canvas.style.height = '200px';
          canvas.width = 400;
          canvas.height = 200;
        }
        
        const ctx = canvas.getContext("2d");
        if (!ctx) {
          console.error("Could not get 2D context for sales chart");
          return;
        }
        
        // Ensure we have valid data before creating the chart
        const labels = this.salesChartData.labels.length > 0 ? this.salesChartData.labels : [
          "1 Oct", "3 Oct", "7 Oct", "10 Oct", "14 Oct", "20 Oct", "23 Oct", "27 Oct", "30 Oct"
        ];
        
        const salesData = this.salesChartData.sales.length > 0 ? this.salesChartData.sales : [1200, 2000, 1800, 1300, 3000, 2500, 180, 1200, 3000];
        const purchasesData = this.salesChartData.purchases.length > 0 ? this.salesChartData.purchases : [200, 1000, 1200, 900, 2500, 2800, 180, 1500, 1800];
        
        // Validate data arrays have the same length
        const maxLength = Math.max(labels.length, salesData.length, purchasesData.length);
        const normalizedLabels = labels.slice(0, maxLength);
        const normalizedSales = salesData.slice(0, maxLength);
        const normalizedPurchases = purchasesData.slice(0, maxLength);
        
        // Ensure we have valid data before creating the chart
        if (!normalizedLabels || !normalizedSales || !normalizedPurchases) {
          console.error("Invalid chart data, cannot create chart");
          return;
        }
        
        // Create chart with simplified configuration to avoid context issues
        this.salesChart = new Chart(ctx, {
          type: "line",
          data: {
            labels: normalizedLabels,
            datasets: [
              {
                label: "المبيعات",
                data: normalizedSales,
                borderColor: "#800080",
                borderWidth: 3,
                tension: 0.4,
                pointRadius: 6,
                pointHoverRadius: 8,
                pointBackgroundColor: "#800080",
                pointBorderColor: "#ffffff",
                pointBorderWidth: 2,
                backgroundColor: "transparent",
                fill: false,
              },
              {
                label: "المشتريات",
                data: normalizedPurchases,
                borderColor: "#D87093",
                borderWidth: 3,
                tension: 0.4,
                pointRadius: 6,
                pointHoverRadius: 8,
                pointBackgroundColor: "#D87093",
                pointBorderColor: "#ffffff",
                pointBorderWidth: 2,
                backgroundColor: "transparent",
                fill: false,
              },
            ],
          },
          options: {
            responsive: true,
            maintainAspectRatio: false,
            interaction: {
              intersect: false,
              mode: 'index',
            },
            animation: {
              duration: 1000,
            },
            scales: {
              x: {
                grid: {
                  display: true,
                  color: 'rgba(0, 0, 0, 0.1)',
                },
                ticks: {
                  color: '#666',
                  font: {
                    size: 12,
                  },
                },
              },
              y: {
                beginAtZero: true,
                grid: {
                  display: true,
                  color: 'rgba(0, 0, 0, 0.1)',
                },
                ticks: {
                  color: '#666',
                  font: {
                    size: 12,
                  },
                  callback: function(value) {
                    return value.toLocaleString();
                  }
                },
              },
            },
            plugins: {
              legend: {
                display: false,
              },
              tooltip: {
                backgroundColor: 'rgba(0, 0, 0, 0.8)',
                titleColor: '#fff',
                bodyColor: '#fff',
                cornerRadius: 8,
                displayColors: true,
                callbacks: {
                  label: function(context) {
                    let label = context.dataset.label || '';
                    if (label) {
                      label += ': ';
                    }
                    if (context.parsed.y !== null) {
                      label += context.parsed.y.toLocaleString();
                    }
                    return label;
                  }
                }
              },
            },
          },
        });
        
        console.log('Sales chart created successfully');
      } catch (error) {
        console.error("Error rendering sales chart:", error);
        // Reset chart instance on error
        this.salesChart = null;
      }
    },
    renderOrdersChart() {
      try {
        const canvas = document.getElementById("orders-chart");
        if (!canvas) {
          console.warn("Orders chart canvas not found");
          return;
        }
        
        // Check if canvas is still in the DOM
        if (!document.contains(canvas)) {
          console.warn("Orders chart canvas is not in the DOM");
          return;
        }
        
        // Destroy existing chart if it exists
        if (this.ordersChart) {
          try {
            this.ordersChart.destroy();
          } catch (destroyError) {
            console.warn("Error destroying orders chart:", destroyError);
          }
          this.ordersChart = null;
        }
        
        // Ensure canvas has proper dimensions before getting context
        if (canvas.width === 0 || canvas.height === 0) {
          canvas.width = canvas.offsetWidth || 400;
          canvas.height = canvas.offsetHeight || 150;
        }
        
        // Additional check to ensure canvas is properly sized
        if (canvas.offsetWidth === 0 || canvas.offsetHeight === 0) {
          canvas.style.width = '400px';
          canvas.style.height = '150px';
          canvas.width = 400;
          canvas.height = 150;
        }
        
        const ctx = canvas.getContext("2d");
        if (!ctx) {
          console.error("Could not get 2D context for orders chart");
          return;
        }
        
        // Create chart with simplified configuration to avoid context issues
        this.ordersChart = new Chart(ctx, {
          type: "line",
          data: {
            labels: this.orderChartData.labels.length > 0 ? this.orderChartData.labels : ["Jan", "Feb", "March", "Apr", "May"],
            datasets: [
              {
                label: "Orders",
                data: this.orderChartData.orders.length > 0 ? this.orderChartData.orders : [10000, 11000, 11756, 10500, 11200],
                borderColor: "#D87093",
                borderWidth: 3,
                fill: false,
                backgroundColor: "transparent",
                tension: 0.4,
                pointRadius: 6,
                pointHoverRadius: 8,
                pointBackgroundColor: "#800080",
                pointBorderColor: "#ffffff",
                pointBorderWidth: 2,
              },
            ],
          },
          options: {
            responsive: true,
            maintainAspectRatio: false,
            interaction: {
              intersect: false,
              mode: 'index',
            },
            animation: {
              duration: 1000,
            },
            scales: {
              x: {
                grid: {
                  display: true,
                  color: 'rgba(0, 0, 0, 0.1)',
                },
                ticks: {
                  color: '#666',
                  font: {
                    size: 12,
                  },
                },
              },
              y: {
                beginAtZero: true,
                grid: {
                  display: true,
                  color: 'rgba(0, 0, 0, 0.1)',
                },
                ticks: {
                  color: '#666',
                  font: {
                    size: 12,
                  },
                  callback: function(value) {
                    return value.toLocaleString();
                  }
                },
              },
            },
            plugins: {
              legend: {
                display: false,
              },
              tooltip: {
                backgroundColor: 'rgba(0, 0, 0, 0.8)',
                titleColor: '#fff',
                bodyColor: '#fff',
                cornerRadius: 8,
                displayColors: true,
                callbacks: {
                  label: function(context) {
                    let label = context.dataset.label || '';
                    if (label) {
                      label += ': ';
                    }
                    if (context.parsed.y !== null) {
                      label += context.parsed.y.toLocaleString();
                    }
                    return label;
                  }
                }
              },
            },
          },
        });
        
        console.log('Orders chart created successfully');
      } catch (error) {
        console.error("Error rendering orders chart:", error);
        // Reset chart instance on error
        this.ordersChart = null;
      }
    },
    openPopup(type, row) {
      this.popupType = type;
      this.selectedRow = { ...row };
      this.isPopupVisible = true;
    },
    closePopup() {
      this.isPopupVisible = false;
      this.popupType = ""; // Reset popup type
      this.selectedRow = null; // Reset selected row
    },
    handlePopupSave(updatedRow) {
      this.saveChanges(updatedRow); // Call saveChanges when popup emits save
    },
    saveChanges(updatedRow) {
      if (this.popupType === "add") {
        updatedRow.id = Date.now(); // Ensure a unique ID for new rows
        this.rows.push(updatedRow);
      } else if (this.popupType === "edit") {
        const index = this.rows.findIndex((row) => row.id === updatedRow.id);
        if (index !== -1) {
          this.rows.splice(index, 1, updatedRow);
        }
      } else if (this.popupType === "delete") {
        this.rows = this.rows.filter((row) => row.id !== updatedRow.id);
      }
      this.closePopup();
    },
    formatDate(dateString) {
      if (!dateString || dateString === "N/A") {
        return "N/A";
      }
      
      try {
        const date = new Date(dateString);
        
        // Check if date is valid
        if (isNaN(date.getTime())) {
          return "Invalid Date";
        }
        
        // Compact date format - always use Gregorian calendar
        const options = {
          year: '2-digit',
          month: '2-digit',
          day: '2-digit',
          hour: '2-digit',
          minute: '2-digit',
          calendar: 'gregory' // Force Gregorian calendar
        };
        
        return date.toLocaleDateString(this.$i18n.locale === 'ar' ? 'ar-SA-u-ca-gregory' : 'en-US', options);
      } catch (error) {
        console.error('Error formatting date:', error);
        return dateString;
      }
    },
         synchronizeChartData() {
       const maxLength = Math.max(
         this.salesChartData.labels.length,
         this.salesChartData.sales.length,
         this.salesChartData.purchases.length
       );

       // Ensure all arrays have the same length and valid data
       this.salesChartData.labels = this.salesChartData.labels.slice(0, maxLength).map(label => 
         label && label !== 'Invalid Date' ? label : 'N/A'
       );
       this.salesChartData.sales = this.salesChartData.sales.slice(0, maxLength).map(sale => 
         typeof sale === 'number' && !isNaN(sale) ? sale : 0
       );
       this.salesChartData.purchases = this.salesChartData.purchases.slice(0, maxLength).map(purchase => 
         typeof purchase === 'number' && !isNaN(purchase) ? purchase : 0
       );
       
       // Ensure we have at least some data
       if (this.salesChartData.labels.length === 0) {
         this.salesChartData.labels = ["Jan", "Feb", "Mar", "Apr", "May"];
         this.salesChartData.sales = [0, 0, 0, 0, 0];
         this.salesChartData.purchases = [0, 0, 0, 0, 0];
       }
     },
  },
};
