          <h3 v-if="type === 'delete'">{{ $t("DeleteRole") }}</h3>
        </div>
        <button class="close-button" @click="$emit('close')">X</button>
      </div>
      <div class="form" v-if="type !== 'delete'">
        <!-- Loading state for edit mode -->
        <div v-if="loading && type === 'edit'" class="loading-container">
          <p>{{ $t("LoadingPermissions") || "Loading permissions..." }}</p>
        </div>
        
        <div v-else>
          <div class="input-container">
            <label>{{ $t("Name") }}</label>
            <input v-model="formData.name" :disabled="type === 'view'" />
          </div>
        <div class="input-container">
          <label>{{ $t("email") }}</label>
          <input v-model="formData.email" :disabled="type === 'view'" />
        </div>
