          <label>{{ $t("password") }}</label>
          <input 
            type="password" 
            v-model="formData.password" 
            :placeholder="$t('enterNewPassword')"
          />
        </div>
        <div class="input-container">
          <label>{{ $t("role") }}</label>
          <div v-if="type === 'view'" class="role-display">
            <span v-for="role in formData.role" :key="role.id || role" class="role-tag">
              {{ typeof role === 'object' ? role.name : role }}
            </span>
          </div>
          <div v-else class="role-selector">
            <select @change="addRole" class="role-dropdown">
              <option value="">{{ $t("selectRole") }}</option>
              <option 
                v-for="role in availableRoles" 
                :key="role" 
                :value="role"
                :disabled="formData.role.some(userRole => {
                  const roleName = typeof userRole === 'object' ? userRole.name : userRole;
                  return roleName === role;
                })"
              >
                {{ role }}
              </option>
            </select>
            <div class="selected-roles">
              <span v-for="role in formData.role" :key="role.id || role" class="role-tag">
                {{ typeof role === 'object' ? role.name : role }}
                <button type="button" @click="removeRole(role)" class="remove-role">&times;</button>
              </span>
            </div>
          </div>
        </div>

        <!-- Permissions Section -->
        <div class="input-container" v-if="formData.role.length > 0">
          <label>{{ $t("Permissions") }}</label>
          <div v-if="type === 'view'" class="permissions-display">
            <div v-for="role in formData.role" :key="role.id || role" class="role-permissions">
              <h4>{{ typeof role === 'object' ? role.name : role }}</h4>
              <div class="permission-tags">
                <span v-for="permission in getSelectedPermissionsForRole(role)" :key="permission" class="permission-tag">
                  {{ $t(permission) }}
                </span>
              </div>
            </div>
          </div>
          <div v-else class="permissions-selector">
            <div class="roles-container">
              <div v-for="role in formData.role" :key="role.id || role" class="role-permission-group">
                <h4>{{ typeof role === 'object' ? role.name : role }}</h4>
                <div class="permission-checkboxes">
                  <div 
                    v-for="permission in rolePermissions[typeof role === 'object' ? role.name : role]" 
                    :key="permission" 
                    class="permission-checkbox"
                  >
                    <input 
                      type="checkbox" 
                      :id="`${typeof role === 'object' ? role.name : role}-${permission}`"
                      :value="permission"
                      v-model="formData.permissions[typeof role === 'object' ? role.name : role]"
                    />
                    <label :for="`${typeof role === 'object' ? role.name : role}-${permission}`">{{ $t(permission) || permission }}</label>
