</template>

<script>
import { useToast } from "vue-toastification";
import axiosInstance from "@/axios.js";

export default {
  props: {
    type: String,
    data: {
      type: Object,
      default: () => ({}),
    },
  },
  data() {
    return {
      formData: {
        ...this.data,
        name: this.data.name || "",
        email: this.data.email || "",
        password: this.data.password || "",
        role: this.data.roles || this.data.role || [], // Handle both roles and role properties
        permissions: this.data.permissions || {},
      },
      availableRoles: [
        "إدارة المنتجات",
        "إدارة الطلبات", 
        "إدارة العملاء",
        "إدارة المطاعم"
      ],
      rolePermissions: {
        "إدارة المنتجات": [
          "ViewProducts",
          "AddProducts",
          "EditProducts",
          "DeleteProducts",
          "ManageInventory",
          "SetPrices"
        ],
        "إدارة الطلبات": [
          "ViewOrders",
          "UpdateOrderStatus",
          "CancelOrders",
          "PrintInvoices",
          "ManageDelivery",
          "ProcessReturns"
        ],
        "إدارة العملاء": [
          "ViewCustomers",
          "AddCustomers",
          "EditCustomerData",
          "DeleteCustomers",
          "ManageComplaints",
          "LoyaltyPrograms"
        ],
        "إدارة المطاعم": [
          "ViewRestaurants",
          "AddRestaurants",
          "EditRestaurants",
          "DeleteRestaurants",
          "ManageMenus",
          "MonitorPerformance"
        ]
      },
      loading: false,
      toast: useToast(),
    };
  },
  async mounted() {
    // Fetch permissions from API when editing
    if (this.type === 'edit' && this.data.id) {
      await this.fetchUserPermissions();
    }
  },
      watch: {
      data: {
        immediate: true,
        handler(newData) {
          this.formData = {
            ...newData,
            name: newData.name || "",
            email: newData.email || "",
            password: newData.password || "",
            role: newData.roles || newData.role || [], // Handle both roles and role properties
            permissions: newData.permissions || {},
          };
        },
      },
    },
  methods: {
    async fetchUserPermissions() {
      this.loading = true;
      try {
        const response = await axiosInstance.get(`v1/admin/roles-permissions/get-user-permissions-for-edit/${this.data.id}`);
        
        if (response.data.status && response.data.data) {
          this.transformApiData(response.data.data);
        } else {
          throw new Error('Invalid response format from API');
        }
      } catch (error) {
        console.error('Error fetching user permissions:', error);
        this.toast.error(error.response?.data?.message || error.message || 'Failed to fetch user permissions');
      } finally {
        this.loading = false;
      }
    },
    
    transformApiData(apiData) {
      // Transform API data to match our component structure
      const transformedRoles = [];
      const transformedPermissions = {};
      
      apiData.forEach(module => {
        // Map module names to Arabic role names
        const roleMapping = {
          'orders': 'إدارة الطلبات',
          'restaurants': 'إدارة المطاعم',
          'customers': 'إدارة العملاء',
          'Products': 'إدارة المنتجات'
        };
        
        const roleName = roleMapping[module.module];
        if (roleName) {
          transformedRoles.push(roleName);
          
          // Transform permissions for this role
          const permissions = module.permissions
            .filter(permission => permission.has_permission)
            .map(permission => permission.name);
          
          transformedPermissions[roleName] = permissions;
        }
      });
      
      // Update the component data
      this.availableRoles = transformedRoles;
      this.rolePermissions = this.getDefaultRolePermissions();
      
      // Update formData with the fetched permissions
      this.formData.role = transformedRoles;
      this.formData.permissions = transformedPermissions;
    },
    
    getDefaultRolePermissions() {
      // Return the default permissions structure based on the API response
      return {
        "إدارة المنتجات": [
          "show Products",
          "add Products", 
          "create Products",
          "update Products",
          "delete Products"
        ],
        "إدارة الطلبات": [
          "show orders",
          "add orders",
          "create orders", 
          "update orders",
          "delete orders"
        ],
        "إدارة العملاء": [
          "show customers",
          "add customers",
          "create customers",
          "update customers", 
          "delete customers"
        ],
        "إدارة المطاعم": [
          "show restaurants",
          "add restaurants",
          "create restaurants",
          "update restaurants",
          "delete restaurants"
        ]
      };
    },
    
    addRole(event) {
      const selectedRole = event.target.value;
      if (selectedRole && !this.formData.role.some(role => {
        const roleName = typeof role === 'object' ? role.name : role;
        return roleName === selectedRole;
      })) {
        this.formData.role.push(selectedRole);
        // Initialize permissions array for the new role
        if (!this.formData.permissions[selectedRole]) {
          this.formData.permissions[selectedRole] = [];
        }
      }
      event.target.value = ""; // Reset select
    },
    removeRole(roleToRemove) {
      this.formData.role = this.formData.role.filter(role => {
        const roleName = typeof role === 'object' ? role.name : role;
        const removeName = typeof roleToRemove === 'object' ? roleToRemove.name : roleToRemove;
        return roleName !== removeName;
      });
      // Remove permissions for the removed role
      const removeName = typeof roleToRemove === 'object' ? roleToRemove.name : roleToRemove;
      if (this.formData.permissions[removeName]) {
        delete this.formData.permissions[removeName];
      }
    },
    getSelectedPermissionsForRole(role) {
      const roleName = typeof role === 'object' ? role.name : role;
      return this.formData.permissions[roleName] || [];
    },
    validateForm() {
      if (!this.formData.name || this.formData.name.trim() === "") {
        this.toast.error(this.$t("Name") + " " + this.$t("isRequired"));
        return false;
      }
      // Ensure email is treated as string before trim
      const emailStr = this.formData.email ? this.formData.email.toString() : "";
      if (!emailStr || emailStr.trim() === "") {
        this.toast.error(this.$t("email") + " " + this.$t("isRequired"));
        return false;
      }
      if (this.formData.role.length === 0) {
        this.toast.error(this.$t("Role") + " " + this.$t("isRequired"));
        return false;
      }
      return true;
    },
    saveRole() {
      if (this.validateForm()) {
        this.$emit("save", this.formData);
        this.toast.success(this.$t("RoleSavedSuccessfully"));
      }
    },
    deleteRole() {
      this.$emit("delete", this.formData.code);
      this.toast.success(this.$t("RoleDeletedSuccessfully"));
    },
  },
};
</script>

