<template>
  <div class="home" :dir="$i18n.locale === 'ar' ? 'rtl' : 'ltr'">
    <div class="Control_panel">
      <div class="table-container">
        <div class="headerTable">
          <div class="icon_text">
            <div class="icon">
              <SvgIcon name="banner"></SvgIcon>
            </div>
            <p>{{ $t("AllBanners") }}</p>
          </div>
          <div class="search_add">
            <div class="search">
              <input type="text" v-model="filter" :placeholder="$t('search')" />
              <SvgIcon class="svg" name="search"></SvgIcon>
            </div>
            <button class="search-button" @click="openPopup('add', {})">
              <p class="addRestbtn">{{ $t("Addbann") }}</p>
              <span class="icon">
                <SvgIcon name="add"></SvgIcon>
              </span>
            </button>

          </div>
        </div>
        <div class="table-responsive">
          <div v-if="loading" class="loading-container">
            <div class="loading-spinner"></div>
            <p>{{ $t("LoadingCategories") }}</p>
          </div>
          <div v-else-if="!rows.length" class="empty-state">
            <p>{{ $t("NoBannersFound") }}</p>
          </div>
          <table v-else>
            <thead>
              <tr class="table-header">
                <th>
                  <div
                    style="
                      display: flex;
                      align-items: center;
                      margin-right: 10px;
                      gap: 5px;
                    "
                  >
                    <SvgIcon name="circle"></SvgIcon>

                    {{ $t("headTable1") }}
                  </div>
                </th>
                <th>{{ $t("head8Table2") }}</th>
                <th>{{ $t("نوع اللافتة") }}</th>
                <th>{{ $t("RestaurantName") }}</th>
                <th>{{ $t("head4Table7") }}</th>
                <th>{{ $t("head8Table5") }}</th>
                <th>{{ $t("AllProcedures") }}</th>
              </tr>
            </thead>
            <tbody>
              <tr
                v-for="rows in filteredRows"
                :key="`slider-${rows.id}`"
              >
                <td
                  style="
                    display: flex;
                    align-items: center;
                    margin-right: 10px;
                    gap: 5px;
                  "
                >
                  <SvgIcon name="dot_circle"></SvgIcon>

                  {{ rows.id }}
                </td>
                <td>
                  <img 
                    v-if="rows.image || rows.photo" 
                    :src="rows.image || rows.photo" 
                    :alt="rows.type"
                    style="width: 50px; height: 50px; object-fit: cover; border-radius: 8px;"
                  />
                  <span v-else>{{ $t("NoImage") }}</span>
                </td>
                <td>{{ getBannerTypeText(rows.type) }}</td>
                <td>
                  <span v-if="rows.type === 'restaurant' && rows.restaurant">
                    {{ rows.restaurant.name }}
                  </span>
                  <span v-else-if="rows.type === 'restaurant' && rows.restaurant_id">
                    {{ getRestaurantName(rows.restaurant_id) }}
                  </span>
                  <span v-else-if="rows.type === 'product' && rows.product">
                    {{ rows.product.name }}
                  </span>
                  <span v-else-if="rows.type === 'product' && rows.product_id">
                    {{ getProductName(rows.product_id) }}
                  </span>
                  <span v-else>
                    {{ $t("NotApplicable") }}
                  </span>
                </td>
                <td>
                  <label class="switch">
                    <input
                      type="checkbox"
                      v-model="rows.approved"
                      @change="updateStatus(rows)"
                    />
                    <span class="slider round"></span>
                  </label>
                </td>
                <td>
                  <label class="switch">
                    <input
                      type="checkbox"
                      v-model="rows.Distinctive"
                      @change="updateStatus(rows)"
                    />
                    <span class="slider round"></span>
                  </label>
                </td>
                <td class="actions">
                  <div class="iconsIctions">
                    <div class="icon" @click="openPopup('edit', rows)">
                      <SvgIcon class="svg" name="edit"></SvgIcon>
                    </div>
                    <div class="icon" @click="openPopup('view', rows)">
                      <SvgIcon class="svg" name="view"></SvgIcon>
                    </div>
                    <div class="icon" @click="openPopup('delete', rows)">
                      <SvgIcon class="svg delete" name="deleteItem"></SvgIcon>
                    </div>
                  </div>
                </td>
              </tr>
            </tbody>
          </table>
        </div>
      </div>
    </div>
  </div>
  <popup-component
    v-if="popupData.visible"
    :type="popupData.type"
    :data="popupData.row"
    @close="closePopup"
    @save="handleSave"
    @delete="confirmDelete"
  />
</template>

<script>
// @ is an alias to /src
import PopupComponent from "@/components/dashboard/popus/bannersPopus.vue";
import SvgIcon from "@/components/SvgIcon.vue";
import axiosInstance from "@/axios.js";

export default {
  name: "addBanners",
  components: {
    PopupComponent,
    SvgIcon,
  },
  data() {
    return {
      filter: "",
      rows: [],
      loading: false,
      restaurants: [], // Cache for restaurant names
      products: [], // Cache for product names
      popupData: {
        visible: false,
        type: "",
        row: null,
      },
      deletePopup: {
        visible: false,
        row: null,
      },
    };
  },
  computed: {
    filteredRows() {
      return this.rows.filter((row) => {
        const searchTerm = this.filter.toLowerCase();
        return (
          (typeof row.type === "string" &&
            row.type.toLowerCase().includes(searchTerm)) ||
          (row.restaurant && 
           row.restaurant.name && 
           row.restaurant.name.toLowerCase().includes(searchTerm)) ||
          (row.product && 
           typeof row.product === "string" &&
           row.product.toLowerCase().includes(searchTerm))
        );
      });
    },
  },
  mounted() {
    this.fetchSliders();
    this.fetchRestaurants();
    this.fetchProducts();
    if (this.$toast) {
      this.$toast.success("Welcome to your dashboard!");
    }
  },
  methods: {
    async fetchSliders() {
      try {
        this.loading = true;
        const response = await axiosInstance.get('v1/admin/sliders');
        
        if (response.data.status) {
          console.log('Raw sliders data:', response.data.data);
          this.rows = response.data.data.map(slider => ({
            ...slider,
            Distinctive: false // Adding this field for the toggle switch
          }));
          console.log('Processed sliders with product_id values:', this.rows.map(s => ({ id: s.id, type: s.type, product_id: s.product_id, restaurant_id: s.restaurant_id })));

        } else {
          console.error('Failed to fetch sliders:', response.data.message);
          if (this.$toast) {
            this.$toast.error(response.data.message || 'Failed to fetch sliders');
          }
        }
      } catch (error) {
        console.error('Error fetching sliders:', error);
        if (this.$toast) {
          this.$toast.error('Error fetching sliders. Please try again.');
        }
      } finally {
        this.loading = false;
      }
    },

    async fetchSingleSlider(id) {
      try {
        const response = await axiosInstance.get(`v1/admin/sliders/${id}`);
        
        if (response.data.status) {
          console.log('Single slider data:', response.data.data);
          return response.data.data;
        } else {
          console.error('Failed to fetch slider:', response.data.message);
          if (this.$toast) {
            this.$toast.error(response.data.message || 'Failed to fetch slider');
          }
          return null;
        }
      } catch (error) {
        console.error('Error fetching slider:', error);
        if (this.$toast) {
          this.$toast.error('Error fetching slider. Please try again.');
        }
        return null;
      }
    },

    async testFetchSlider(id) {
      console.log(`Testing fetch slider with ID: ${id}`);
      const sliderData = await this.fetchSingleSlider(id);
      if (sliderData) {
        console.log('Successfully fetched slider:', sliderData);
        // Open the slider in view mode
        this.openPopup('view', sliderData);
      }
    },

    async fetchRestaurants() {
      try {
        const response = await axiosInstance.get('v1/admin/restaurants');
        
        if (response.data.status) {
          this.restaurants = response.data.data.map((item) => ({
            id: item.id,
            name: item.name || "N/A",
            logo: item.logo,
            phone: item.phone,
            description: item.description
          }));

        } else {
          console.error("Failed to fetch restaurants:", response.data.message);
        }
      } catch (error) {
        console.error("Error fetching restaurants:", error);
      }
    },

    async fetchProducts() {
      try {
        const response = await axiosInstance.get('v1/admin/products');
        
        if (response.data.status) {
          console.log('Raw products data:', response.data.data);
          this.products = response.data.data.map((item) => ({
            id: item.id,
            name: item.name || "N/A",
            price: item.price,
            calories: item.calories,
            description: item.description,
            cover_image: item.cover_image,
            productCategory: item.productCategory
          }));
          console.log('Processed products:', this.products);

        } else {
          console.error("Failed to fetch products:", response.data.message);
        }
      } catch (error) {
        console.error("Error fetching products:", error);
      }
    },

    getRestaurantName(restaurantId) {
      console.log('getRestaurantName called with restaurantId:', restaurantId, 'type:', typeof restaurantId);
      console.log('Available restaurants:', this.restaurants);
      
      // Handle different data types for restaurantId
      const restaurant = this.restaurants.find(r => {
        // Convert both to strings for comparison to handle type mismatches
        const rId = String(r.id);
        const searchId = String(restaurantId);
        return rId === searchId;
      });
      
      console.log('Found restaurant:', restaurant);
      return restaurant ? restaurant.name : 'Unknown Restaurant';
    },

    getProductName(productId) {
      console.log('getProductName called with productId:', productId, 'type:', typeof productId);
      console.log('Available products:', this.products);
      
      // Handle different data types for productId
      const product = this.products.find(p => {
        // Convert both to strings for comparison to handle type mismatches
        const pId = String(p.id);
        const searchId = String(productId);
        return pId === searchId;
      });
      
      console.log('Found product:', product);
      return product ? product.name : 'Unknown Product';
    },
    
    getBannerTypeText(type) {
      const typeMap = {
        'restaurant': 'لافتة المطعم',
        'product': 'لافتة المنتج',
        'offer': 'لافتة العروض',
        'general': 'لافتة عامة'
      };
      return typeMap[type] || type;
    },
    
    async updateStatus(row) {
      try {
        // Make API call to change approval status
        // Try PATCH first, if that fails, we'll need to check the correct endpoint
        const response = await axiosInstance.patch(`v1/admin/sliders/change-approval/${row.id}`, {
          approved: row.approved
        });
        
        if (response.data.status) {
          if (this.$toast) {
            this.$toast.success(response.data.message || 'Status updated successfully');
          }
        } else {
          // Revert the toggle if the API call failed
          row.approved = !row.approved;
          if (this.$toast) {
            this.$toast.error(response.data.message || 'Failed to update status');
          }
        }
      } catch (error) {
        // Revert the toggle if there was an error
        row.approved = !row.approved;
        console.error('Error updating status:', error);
        
        // Check if it's a method not allowed error
        if (error.response && error.response.data && error.response.data.allowed_methods) {
          if (this.$toast) {
            this.$toast.error(`HTTP method not allowed. Allowed methods: ${error.response.data.allowed_methods}`);
          }
        } else {
          if (this.$toast) {
            this.$toast.error('Failed to update status. Please try again.');
          }
        }
      }
    },
    
    async openPopup(type, row) {
      // Ensure proper data formatting for editing
      let formattedRow = { ...row };
      
      if (type === 'add') {
        // For new banners, ensure we start with empty data
        formattedRow = {
          type: '',
          restaurant_id: '',
          product_id: '',
          photo: null
        };
      } else if (type === 'view' && row && row.id) {
        // Fetch fresh data for viewing
        const sliderData = await this.fetchSingleSlider(row.id);
        if (sliderData) {
          formattedRow = sliderData;
        }
      } else if (type === 'edit' && row) {
        // If this is a restaurant banner (has restaurant data), ensure type is set
        if (row.restaurant || row.restaurant_id) {
          formattedRow.type = 'restaurant';
        }
        
        // If this is a product banner (has product data), ensure type is set
        if (row.product || row.product_id) {
          formattedRow.type = 'product';
        }
        
        // Ensure restaurant_id is set from restaurant object if available
        if (row.restaurant && row.restaurant.id && !row.restaurant_id) {
          formattedRow.restaurant_id = row.restaurant.id;
        }
        
        // Ensure product_id is set from product object if available
        if (row.product && row.product.id && !row.product_id) {
          formattedRow.product_id = row.product.id;
        }
      }
      

      this.popupData = {
        visible: true,
        type,
        row: formattedRow,
      };
    },
    
    closePopup() {
      this.popupData.visible = false;
    },
    
    async handleSave(updatedRow) {
      try {
        // Create FormData for file upload
        const formData = new FormData();
        
        // Add type
        formData.append('type', updatedRow.type);
        
        // Add restaurant_id only if type is restaurant
        if (updatedRow.type === 'restaurant' && updatedRow.restaurant_id) {
          formData.append('restaurant_id', updatedRow.restaurant_id);
        }
        
        // Add product_id only if type is product
        if (updatedRow.type === 'product' && updatedRow.product_id) {
          formData.append('product_id', updatedRow.product_id);
        }
        
        // Handle image upload
        if (updatedRow.photo) {
          // If photo is a base64 string, convert it to a file
          if (typeof updatedRow.photo === 'string' && updatedRow.photo.startsWith('data:')) {
            const response = await fetch(updatedRow.photo);
            const blob = await response.blob();
            const file = new File([blob], 'banner-image.jpg', { type: 'image/jpeg' });
            formData.append('image', file);
          } else if (updatedRow.photo instanceof File) {
            formData.append('image', updatedRow.photo);
          } else if (typeof updatedRow.photo === 'string' && !updatedRow.photo.startsWith('data:')) {
            // If it's a URL string, append it as is
            formData.append('image', updatedRow.photo);
          }
        }

        if (this.popupData.type === "edit") {
          // Update existing slider using _method=PUT
          formData.append('_method', 'PUT');
          console.log('Sending formData for edit with _method=PUT:', formData);
          const response = await axiosInstance.post(`v1/admin/sliders/${updatedRow.id}`, formData, {
            headers: {
              'Content-Type': 'multipart/form-data'
            }
          });
          if (response.data.status) {
            const index = this.rows.findIndex(row => row.id === updatedRow.id);
            if (index !== -1) {
              this.rows.splice(index, 1, { ...response.data.data, Distinctive: updatedRow.Distinctive });
            }
            if (this.$toast) {
              this.$toast.success('Slider updated successfully');
            }
          }
        } else if (this.popupData.type === "add") {
          // Add new slider
          console.log('Sending formData for add:', formData);
          const response = await axiosInstance.post('v1/admin/sliders', formData, {
            headers: {
              'Content-Type': 'multipart/form-data'
            }
          });
          if (response.data.status) {
            this.rows.push({ ...response.data.data, Distinctive: false });
            if (this.$toast) {
              this.$toast.success('Slider added successfully');
            }
          }
        }
        this.closePopup();
      } catch (error) {
        console.error('Error saving slider:', error);
        if (this.$toast) {
          this.$toast.error('Failed to save slider');
        }
      }
    },
    
    async confirmDelete(row) {
      try {
        const response = await axiosInstance.delete(`v1/admin/sliders/${row.id}`);
        if (response.data.status) {
          const index = this.rows.findIndex(r => r.id === row.id);
          if (index !== -1) {
            this.rows.splice(index, 1);
          }
          if (this.$toast) {
            this.$toast.success('Slider deleted successfully');
          }
        }
        this.closePopup();
      } catch (error) {
        console.error('Error deleting slider:', error);
        if (this.$toast) {
          this.$toast.error('Failed to delete slider');
        }
      }
    },
  },
};
</script>
