<template>
  <DashboardBox 
    :title="$t('Orders') || 'N/A'" 
    :count="dataDashboard.ordersCount || 0"
  >
    <template #icon>
      <OrdersIcon />
    </template>
  </DashboardBox>

  <DashboardBox 
    :title="$t('CompletedOrders') || 'N/A'" 
    :count="dataDashboard.doneOrdersCount || 0"
  >
    <template #icon>
      <CompletedOrdersIcon />
    </template>
  </DashboardBox>

  <DashboardBox 
    :title="$t('totalClients') || 'N/A'" 
    :count="dataDashboard.totalClients || 0"
  >
    <template #icon>
      <ClientsIcon />
    </template>
  </DashboardBox>

  <DashboardBox 
    :title="$t('ApprovedRestaurants') || 'N/A'" 
    :count="dataDashboard.totalApprovedRestaurants || 0"
  >
    <template #icon>
      <RestaurantsIcon />
    </template>
  </DashboardBox>
</template>

<script>
import axios from "axios";
import DashboardBox from "./DashboardBox.vue";
import OrdersIcon from "./icons/OrdersIcon.vue";
import CompletedOrdersIcon from "./icons/CompletedOrdersIcon.vue";
import ClientsIcon from "./icons/ClientsIcon.vue";
import RestaurantsIcon from "./icons/RestaurantsIcon.vue";

export default {
  name: "OrderSummary",
  components: {
    DashboardBox,
    OrdersIcon,
    CompletedOrdersIcon,
    ClientsIcon,
    RestaurantsIcon
  },

  data() {
    return {
      dataDashboard: {
        ordersCount: 0,
        doneOrdersCount: 0,
        totalApprovedRestaurants: 0,
        totalClients: 0,
      }, // Initialized properties
    };
  },
  mounted() {
    this.fetchDashboardData();
  },
  methods: {
    fetchDashboardData() {
      const token = localStorage.getItem("authToken");
      axios
        .get(
          "https://backend.alaqdk.com/api/v1/admin/dashboard/get-dashboard-data",
          {
            headers: {
              "Accept-Language": "ar",
              Authorization: `Bearer ${token}`,
            },
          }
        )
        .then((response) => {
          console.log("API Response:", response.data);
          const data = response.data;
          if (data.status) {
            this.dataDashboard = data.data || {};
            console.log(data.data);
          } else {
            console.error("Failed to fetch dashboard data:", data.message);
          }
        })
        .catch((error) => {
          console.error("Error fetching dashboard data:", error);
        });
    },
  },
};
</script>
